INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('action-man-robot-atak', 6299, '2004-09-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gc6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scutnr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Action Man: Robot Atak', 'Action Man: Robot Atak is based on the direct-to-DVD animated film of the same name, in turn based on the line of toys. To stop the evil Dr. X and his army of robots that have been attacking cities across the globe, Action Force seek out his secret hideout, Island X. Dropped on different parts of the island, Action Man, Redwolf and Flint must first find each other, and then put an end to the evil doctor''s plans. Most of the game''s 17 levels take the form of a side-scrolling platformer with a heavy action focus. To get to the level exit, the controlled character must jump pits and gaps, climb ledges and take out many enemies, different varieties of X'' robots and various animals native to the island: spiders, bats, even dinosaurs. Each character has slightly different abilities (until the finale, which hero is controlled depends on the level): Native American Redwolf always carries his bow, while Action Man and Flint start most levels with only their fists. They can pick up weapons, though, including throwing discs (for Action Man only), several different guns (which can be further enhanced by timed power-ups) and a boomerang (for Australian Flint only). Only Flint can double jump. Picking up 50 Action Man icons gives an extra life. Regular extra lives and health power-ups are also available, and a reset checkpoint is available every few screens. Variety from the platform levels comes in two levels where Flint uses his dirt rider and Redwolf surfs the waves. These are seen from behind the heroes as they must avoid or blast away obstacles and collect Action Man icons. Action Man lives up to his name in a level where he rides a motorcycle up a volcano (shooting missiles at enemies and jumping across gaps) and another one where he straps helicopter blades to his back to fly towards the level end.' FROM games WHERE igdb_id = 6299 ON CONFLICT (game_id, language_code) DO NOTHING;
