INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sukebooo-man', 288154, '2004-06-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7sz2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqq8t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sukebooo Man', 'This side-scrolling extreme sports game puts a side-scrolling spin on the skateboarding craze of the 2000s. Players jump their way through 2D platforming levels, complete with bottomless pits and floating platforms, while collecting burgers. Instead of running through like in a traditional platformer, though, they skate their way through. Players can perform various tricks while flying through the air, racking up points by doing tricks and combos. Players compete for high scores on each level, balancing collecting burgers and performing complex series of tricks to maximize their score.' FROM games WHERE igdb_id = 288154 ON CONFLICT (game_id, language_code) DO NOTHING;
