INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Suite Life of Zack & Cody: Pizza Party Pickup!', 'This time, the twins have to work together to beat Maddie and London on a quest to throw the best pizza party of the summer. The hotel can seem like a maze sometimes, which is why the kids need your help! Navigate the hallways, and collect all the pizza, snacks, and cool stuff needed for an epic party.' FROM games WHERE igdb_id = 281323 ON CONFLICT (game_id, language_code) DO NOTHING;
