INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fast and The Furious', 'The Fast and the Furious (Wild Speed in Japan) is a racing video game licensed by the film of the same name. The game was released in several versions, first was the so-called "2D version" developed and published by I-Play for mobile phones and released on March 4, 2004 and then the so-called "arcade version" developed and published by Raw Thrills for Arcade in July 2004 (the game is a spiritual successor to the saga Cruis''n; containing similar elements and the design of Eugene Jarvis), and later I-Play releases the so-called "3D version" developed by Juice Games for mobile phones in September 2005.' FROM games WHERE igdb_id = 152308 ON CONFLICT (game_id, language_code) DO NOTHING;
