INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '18 Wheels of Steel: Pedal to the Metal', 'FEEL THE POWER! LIVE THE DREAM! Take your show on the road. Drive your rig to make it big and build your business. Money talks - when you''re in charge, let the drivers to their job while you count your cash. You''re not only a trucker, you''re a truck tycoon. CAN YOU HANDLE THE BIG JOBS? Damaged goods eat your profits. Keep it shiny side up maneuvering through dangerous changing weather conditions.' FROM games WHERE igdb_id = 37046 ON CONFLICT (game_id, language_code) DO NOTHING;
