INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie: The Princess and the Pauper', 'Barbie as the Princess and the Pauper is based on Barbie''s home video take on the favorite fable. Erika are Anneliese beauties from two different worlds -- one a girl about town, the other a princess high in the land. When trouble starts in the kingdom, the two will have to solve puzzles and jump across dangers in 20 stages of adventure. Barbie as the Princess and the Pauper features two-player minigames and the ability to play as Erika, Anneliese, and even the royal cats Wolfie and Serafina!' FROM games WHERE igdb_id = 45169 ON CONFLICT (game_id, language_code) DO NOTHING;
