INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('airstrike-2', 137272, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4pbn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgrd1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AirStrike 2', 'In 2004, DivoGames Ltd., rondomedia Marketing & Vertriebs GmbH publishes AirStrike 2 on Windows. AirStrike 2 is a singleplayer and multiplayer bird''s-eye view shooter game in the AirStrike series. Following the previous AirStrike game, the N.I.T.O. terrorists'' main plan was defeated. However their terrorism remains a threat and when a spy satellite is shot down by a suspected N.I.T.O. base, pilot Zero-Two is called back into action. With brand new helicopters and weapons, Zero-Two is ready to begin a new Air Strike and fight his way through the enemy forces. AirStrike 2 shares the same gameplay as its predecessor, being a vertically scrolling shooter that can be played at a 3-D angle or the more traditional 2-D top-view mode. The player chooses his mission and from among 6 different helicopters, whose speed and armor vary. Each mission begins by a briefing from HQ. Once in flight, the action begins, where the player can fire forward in front of them at enemy opponents and installations. Different power-ups can be found which change the primary weapon or missile type being used as well as special weapons. There are 18 levels to complete, over 100 enemy units to destroy including 3 bosses, 5 types of hostile terrain and a whole lot of power-ups and bonuses.' FROM games WHERE igdb_id = 137272 ON CONFLICT (game_id, language_code) DO NOTHING;
