INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Hearts: Covenant', 'Shadow Hearts: Covenant is a direct continuation of Shadow Hearts; Its story starts a year and a half after the first one in the midst of World War I. It focuses on Karin Koenig, a lieutenant in the German Army who assists in the exorcism of a man able to turn into demons, Yuri Volte Hyuga. However, after learning of Yuri''s caring nature, Karin goes on a quest with him to save him from a spell inside him and are drawn into a conflict involving demons of demonolatry.' FROM games WHERE igdb_id = 4171 ON CONFLICT (game_id, language_code) DO NOTHING;
