INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('casino-challenge', 44640, '2004-01-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zog.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schxk2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casino Challenge', 'Casino Challenge simulates all the fun and thrills of a real live casino, allowing you to re-create all the thrills of the gaming action you find in real casinos from Las Vegas to Monte Carlo. Choose your game and hit the tables. All the great and classic casino games are included in this one exciting package, including blackjack, simulated live horse racing, roulette and even jackpot-style slot machines. Playing Casino Challenge gives you an insight into how to play casino games more effectively; you can learn the secrets and develop your own play strategies the more you play and practice.' FROM games WHERE igdb_id = 44640 ON CONFLICT (game_id, language_code) DO NOTHING;
