INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Warcraft', 'World of Warcraft is a massively multiplayer online roleplaying game (MMORPG) set in the Warcraft universe. Players assume the roles of Warcraft heroes as they explore, adventure, and quest across a vast world. Being "Massively Multiplayer," World of Warcraft allows thousands of players to interact within the same world. Whether adventuring together or fighting against each other in epic battles, players will form friendships, forge alliances, and compete with enemies for power and glory.' FROM games WHERE igdb_id = 123 ON CONFLICT (game_id, language_code) DO NOTHING;
