INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moe Moe: No Limit Off Beat Action Shooting', 'A doujin game created by the now defunct Japanese team Make Of Enjoy (M. O. E.). This game is a platform fighting game featuring characters from various Manga and Visual Novel franchises, as well as two original characters. This game focuses on projectile shooting combat, and features character-specific specials and supers.' FROM games WHERE igdb_id = 343416 ON CONFLICT (game_id, language_code) DO NOTHING;
