INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mega-man-x-command-mission', 1751, '2004-07-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coblt2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7z7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man X: Command Mission', 'Mega Man X: Command Mission, known as Rockman X Command Mission in Japan, is a spin-off game in the Mega Man X series. It was released in 2004 on both the PlayStation 2 and the Nintendo GameCube, making it the second-to-last game in the Mega Man X series to be released. Unique to the series, it is an RPG featuring turn-based combat and an extensive story. It plays quite similarly to Capcom''s signature Breath of Fire series in a number of ways, due to the shared development team. Chronologically, it is currently the Mega Man X game set furthest in the future, taking place sometime in the twenty-third century (22XX time period); however, it is also set in an alternate timeline outside of the main storyline of the Mega Man series. The Gamecube version let''s you link up to Game Boy Advance so you can use the GBA as a treasure hunter locater. The PS2 version contains a Mega Man X8 Demo.' FROM games WHERE igdb_id = 1751 ON CONFLICT (game_id, language_code) DO NOTHING;
