INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GunGriffon: Allied Strike', 'GunGriffon: Allied Strike takes place in a hostile futuristic world where there is little hope for survival among the human race. The player takes on the role of a renegade soldier, enlisted in an anti-tank troop, whose prime mission is to take down armored tanks, the ultimate ground weapon used to destroy the earth and any living thing that gets in its way. The player uses his entrusted machine, a "High Mac" (High-Mobility Armored Combat System), to fight the battery of armed soldiers and sinister machines that await them on the battlefield. The game features full Xbox Live compatibility with a multi-player online mode and a variety of missions.' FROM games WHERE igdb_id = 47355 ON CONFLICT (game_id, language_code) DO NOTHING;
