INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bazooka Cafe', 'Bazooka Cafe is an interactive dating-sim that explores life as the manager of a cafe staffed by very well-endowed Japanese maids. A kyonyuu (big-breasted) romantic comedy with great art from Kohaku Sumeragi, with plenty of fun sex, and situational humor. This is a game that you won''t want to miss!' FROM games WHERE igdb_id = 72633 ON CONFLICT (game_id, language_code) DO NOTHING;
