INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Racing Gears Advance', 'Choose from 12 officially licensed supercars from top manufacturers including Dodge, Lotus, Chevy, Mitsubishi, GM and more. Kick it into gear and race like a pro as you power-slide through tough turns and take hidden shortcuts to reach the finish line. Feel the exhilaration of stopping another racer in their tracks with a well placed rocket. But be sure to upgrade your supercar and bring the right tires, as the Racing Gears League continues whether rain or snow. Team up with your friends for multi-player racing action.' FROM games WHERE igdb_id = 6551 ON CONFLICT (game_id, language_code) DO NOTHING;
