INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen MX', 'Super Robot Taisen MX is a video game for the PlayStation 2. It is part of the Super Robot Wars series by Banpresto, a division of Bandai, and was released on May 27, 2004. It was later ported to the PlayStation Portable on December 19, 2005, with minor gameplay tweaks, titled Super Robot Wars MX Portable.' FROM games WHERE igdb_id = 72849 ON CONFLICT (game_id, language_code) DO NOTHING;
