INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ESPN Baseball 2K4', 'Spiritual successor to World Series Baseball, ESPN MLB raises the bar with Power Pitching, Online Gameplay and ESPN presentation featuring Jon Miller and Karl Ravech. Take complete control of the mound with new pitches, pitch speeds, pitch interface, pitch animations, pitcher momentum and exclusive ESPN K-Zone pitch analysis. Experience seamless online gameplay for PlayStation 2. Hundreds of new, break-through animations including broken bats, mound conferences, on-deck batters, curtain calls, and player reactions. The developers also added a new General Manager Mode -- now you''ll have to answer to the owners if you can''t keep your club running on all cylinders. If you don''t make wise decisions, you can get fired by your team or, if successful, be lured away by other teams.' FROM games WHERE igdb_id = 43249 ON CONFLICT (game_id, language_code) DO NOTHING;
