INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Natsuiro: Hoshikuzu no Memory', 'This is an adventure game originally released on PC, depicting a story of pure love with girls met during a lakeside summer vacation. The PlayStation 2 edition features an enhanced storyline, with new events and CG illustrations added. After the death of his father, the protagonist returns to his hometown villa for the first time in many years. There, he meets four girls, and through their interactions, his sorrowful memories gradually transform into gentle, cherished ones.' FROM games WHERE igdb_id = 379674 ON CONFLICT (game_id, language_code) DO NOTHING;
