INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-quest-viii-journey-of-the-cursed-king', 1819, '2004-11-27', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7vf2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uzjjerd7zltk8tnp74ki.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest VIII: Journey of the Cursed King', 'Dragon Quest VIII: Journey of the Cursed King is the eighth installment in the Dragon Quest series, developed by Level-5 and published by Square Enix for the PlayStation 2 video game console. It was also later released for the Nintendo 3DS in 2015. It is a traditional Japanese-style role-playing game with random enemy encounters, simple turn-based combat mechanics, and management of a party consisting of four characters, each belonging to a clearly defined class. Unlike its predecessors in the series and most Japanese RPGs in general, the game features a continuous world with fairly vast landscapes and integrated towns and dungeons, as opposed to world map traveling and locations represented by icons. The game features full camera rotation and optional first-person view. Like in the previous Dragon Quest games, many objects can be interacted with; for example, barrels can be physically lifted, carried, and broken, to reveal items hidden within.' FROM games WHERE igdb_id = 1819 ON CONFLICT (game_id, language_code) DO NOTHING;
