INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scene It?: The DVD Movie Game', 'Scene It?: The DVD Movie Game is first game in the Scene It? series and can be played by two to four players or teams. The box contains a folding game board, Reference cards, Trivia cards and Buzz cards together with four metal tokens; a film reel, a box of popcorn, a clapper board, and a movie camera, the DVD is held in a card slip case. The game is played on the Scene It? ''flex-time'' game board so-called because of its novel feature, when there''s not enough time/interest to play a full game it can be folded, thus reducing it''s size so that a short game can be played.' FROM games WHERE igdb_id = 359901 ON CONFLICT (game_id, language_code) DO NOTHING;
