INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashen', 'Ashen is a supernatural horror-themed FPS developed exclusively for the N-Gage platform. When Seven River City is plunged into chaos, stricken by storms and overcome with supernatural phenomena, Jacob Ward is filled with dread and despair, like most others. Yet Ward knows more about this catastrophe than most, and as its citizens flee, he must return to Seven River City and work to save it. Somewhere in that half-ruined darkness is his sister, a woman Ward believes is responsible for this disaster; a woman who warned him this would happen.' FROM games WHERE igdb_id = 6259 ON CONFLICT (game_id, language_code) DO NOTHING;
