INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xs-moto', 49350, '2004-07-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ou9xqoouds6hlo1dxhsc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XS Moto', 'Based on the XS Games'' 2002 release for PlayStation, XS Moto offers fullthrottle motorcycle racing with a variety of bike, track, difficulty, and play mode options. As players demonstrate their virtual riding skills, addition options are unlocked to challenge them further. Publisher XS Games drafted DC Studios to develop the game. Featuring 12 different tracks and four bikes, XS Moto runs on the same engine and technology built for Majesco''s Cartoon Network Speedway. In addition to standard racing game controls, the game also features a bike-specific gameplay element. The upper corner indicates a "balance" meter that flashes when players get close to falling off their bikes, and to stay up players must use both the L and R with the D-pad during turns.' FROM games WHERE igdb_id = 49350 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49350 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
