INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkstalkers Chronicle: The Chaos Tower', 'Once again, the monster warriors from the Darkstalkers series return to battle for control of the night. From vampires to mummies, Darkstalkers Chronicle: The Chaos Tower includes all 18 characters from previous installments in the franchise. Choose your favorite character, and master his or her unique moves to gain victory in various gameplay modes, such as arcade, training, tower, and Ad-Hoc.' FROM games WHERE igdb_id = 20011 ON CONFLICT (game_id, language_code) DO NOTHING;
