INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Breaker', 'Chaos Breaker/Dark Awake: The King Has No Name is a fantasy-themed sprite-based 2D fighting game developed by Eolith and released exclusively in Japan arcades. Players select a team of 3 characters, similar to The King of Fighters series. There are 18 playable characters, 3 bosses, and six different races featured in the game, including: Human, Dark Elf, Elf, Orc, Dwarf, and Undead.' FROM games WHERE igdb_id = 76597 ON CONFLICT (game_id, language_code) DO NOTHING;
