INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: The Battle of Yavin', 'Star Wars: The Battle of Yavin is a 3D Shooter Game where you play as Luke Skywalker in the epic battle of Yavin. Your mission is to assault and destroy the Empire''s Death Star. Fight in space, on the Death Star''s surface, make the trench run, and try not to get blasted by Darth Vader''s ship. Six stages of intense action.' FROM games WHERE igdb_id = 8147 ON CONFLICT (game_id, language_code) DO NOTHING;
