INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Home on the Range', 'The Home on the Range GBA takes up where the movie left off. Alameda Slim, Rico and the three Willies have escaped from jail and are up to their old tricks. Ever since Buck, Maggie and the other farm animals helped put the outlaws behind bars, they have been schemin'' to escape jail. Now, they''re out and it''s up to Buck, Jeb, Lucky Jack and the others to round them up once more! Many familiar locations from the film are revisited in this high-spirited action adventure.' FROM games WHERE igdb_id = 49153 ON CONFLICT (game_id, language_code) DO NOTHING;
