INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Lilo & Stitch 2: Hämsterviel Havoc', 'Play as both Stitch and Lilo to rescue Nani and David, who have been kidnapped by the evil Hämsterviel and taken onboard his spaceship. To complicate things, Hämsterviel created evil alien Experiments that go head-to-head with our heroes. Start by capturing each Experiment and harnessing its special power in order to progress and capture the next. Sparky, Experiment 221, helps you out with his powerful electricity balls, while Richter, Experiment 513, shakes things up by igniting an earthquake. Gameplay modes include platform-shooting as Stitch, navigation and strategy as Lilo, intense racing, and multiplayer mode.' FROM games WHERE igdb_id = 49261 ON CONFLICT (game_id, language_code) DO NOTHING;
