INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yojijukugo Flash', 'Yojijukugo Flash is a free mini Flash game provided by GAMEDESIGN. "Yojijukugo" is a Japanese idiom consisting of 4 kanji. In each stage, some kanji are randomly placed. The goal is to construct Yojijukugo by rearranging them with a mouse in all 7 stages.' FROM games WHERE igdb_id = 141329 ON CONFLICT (game_id, language_code) DO NOTHING;
