INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legend-of-zelda-navi-trackers', 91680, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3z6i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc898p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Navi Trackers', 'The Legend of Zelda: Navi Trackers was formerly planned as stand alone game, under the subtitle of Tetra''s Trackers, but ended up being released as one of the game in the japanese version of The Legend of Zelda: Four Swords Adventures (Four Swords +). In this game, multiple players, using a combination of the television screen and Game Boy Advances, search for members of Tetra''s pirate gang to gain stamps from them, as many as possible within a given time limit. All action takes place on the Game Boy Advance used by each player, with the television screen showing a basic map, and Tetra narrating the action. The game was first intended to be a remake of BS Marvelous: Time Athletic, but changing the franchise to Zelda. Assets based on BS Marvelous were found in the final game.' FROM games WHERE igdb_id = 91680 ON CONFLICT (game_id, language_code) DO NOTHING;
