INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tales-of-rebirth', 1205, '2004-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ywc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc83cs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Rebirth', 'Tales of Rebirth is set in a world where humans (called Huma) and beast people (Gajuma) coexist in relative peace. The world''s magical power is called Force, which manifests in various people as control over an element or aspect of the physical laws. In ancient times, after a war sparked when Huma attempted to enslave Gajuma, both races joined forces to found the kingdom of Karegia. An unspecified time before the events of the game, Geyorkias, the ruler of a spirit race called the Sacred Beasts, sought to destroy the Huma as their dark emotions were fueling a primordial destructive force known as Yuris: the other Sacred Beasts put a stop to Geyorkias'' plan by sealing him away, then acting to nullify Yuris'' threat. The story opens with the death of Karegia''s king, Ladras Lindblum, poisoned by the royal adviser Zilva Madigan: during his final moments, he releases his power into the world, causing many humans to become possessed by Force, including Veigue, Annie and Tytree. As the king has failed to name a successor, Karegia enters an interregnum at his death.' FROM games WHERE igdb_id = 1205 ON CONFLICT (game_id, language_code) DO NOTHING;
