INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half-Life: Source', 'Half-Life: Source is a port of Valve''s original acclaimed game Half-Life to their new Source engine used for Half-Life 2. It takes advantage of vertex and pixel shaders to create realistic water effects, and can now portray realistic physics effects. It also has new menus, improved lighting and soft shadows, ragdoll character animations, and a 3D skybox replacing the old 16-bit color prerendered bitmap skies.' FROM games WHERE igdb_id = 6744 ON CONFLICT (game_id, language_code) DO NOTHING;
