INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Dash', 'In Pokémon Dash, you''ll control Pikachu and race against other Pokémon. Use the DS''s touch screen to adjust Pikachu''s direction and speed. Off the course, Pikachu can cross water terrain by riding on Lapras'' back and fly using a hot-air balloon.' FROM games WHERE igdb_id = 18594 ON CONFLICT (game_id, language_code) DO NOTHING;
