INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors', 'A portable version of Dynasty Warriors released for the PSP in 2004 in Japan and in 2005 in North America and Europe, being one of the launch titles for this console in both North America and Japan. It adds new modes to the Dynasty Warrior franchise. Unlike previous games, it allows the player to have up to four deployable officers to accompany them during battle. These officers range from characters who are otherwise playable to generic officers with unique skills and traits.' FROM games WHERE igdb_id = 100279 ON CONFLICT (game_id, language_code) DO NOTHING;
