INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: Quest for Cinnabar', 'Tomb Raider: Quest for Cinnabar is the second opus of Tomb Raider games on mobile phones. The game keeps the original main principle of gameplay in a side view scrolling game where guns, objects to collect and puzzles to solve are still more than present. Control Lara Croft into fifteen levels of gameplay where Lara will still have to jump, climb, use guns, action objects everywhere in order to discover the Cinnabar and return it to England.' FROM games WHERE igdb_id = 165177 ON CONFLICT (game_id, language_code) DO NOTHING;
