INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Dead Revolver', 'Red Dead Revolver is a 2004 action-adventure game developed by Rockstar San Diego and published by Rockstar Games. It is the first entry in the Red Dead series and was released for the PlayStation 2 and Xbox in May 2004. Set in the 1880s, during the American frontier, the single-player story follows bounty hunter Red Harlow''s quest for revenge after the murder of his parents. A local multiplayer mode allows up to four players to face off against each other or AI-controlled bots in free-for-all battles.' FROM games WHERE igdb_id = 1969 ON CONFLICT (game_id, language_code) DO NOTHING;
