INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto: Ultimate Ninja 2', '"The ultimate ninja battle returns! Battle the best in the land with intense, anime-style head-to-head ninja fighting with over 30 playable characters and 16 unique stages. Choose from more than 60 exciting missions, test your skills with challenging mini-games or play through the anime storyline - and even unlock an original story - in the all-new mode, Ultimate Road. Earn money and points to unlock tons of bonus content as you unleash your chakra and ascend the ranks on your way to becoming the greatest ninja of all!"' FROM games WHERE igdb_id = 19621 ON CONFLICT (game_id, language_code) DO NOTHING;
