INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('neocron-2-beyond-dome-of-york', 79753, '2004-09-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5v6w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scka4t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neocron 2: Beyond Dome of York', 'Neocron 2: Beyond Dome of York is a 2004 video game which is a follow-up to 2002''s Neocron. Originally slated to be an expansion pack Neocron 2 was released separately under a new publisher, 10tacle Studios AG. Neocron 2 features a large persistent world and massive multiplayer gaming. Divided into two factions, Neocron and Dome of York, and separated by the vast radiated wastelands between the cities, the players try to build a career in one of the many industrial and military organizations. There are various player classes offered, including different types of fighters, PSI powered monks and hackers. The game allows free exploring of the world, NPC missions or engaging in PvP-combat, using an Egoshooter-like interface for gameplay and fighting. Noteworthy features, amongst others, are the Hacknet (a network similar to the matrix of the pen&paper-game Shadowrun) which allows skilled hackers to travel the whole game-world through a great number of network nodes or attack enemy bases and the usability of driving and flying vehicles in the wastelands.' FROM games WHERE igdb_id = 79753 ON CONFLICT (game_id, language_code) DO NOTHING;
