INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-stunt-track-challenge', 5862, '2004-11-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2f94.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels: Stunt Track Challenge', 'Hot Wheels Stunt Track Challenge and Hot Wheels World Race is the hottest, most extreme Game Show out there! Fearless drivers impress the audience by beating the competitors and performing wild stunts to win Episodes and better cars. At the end of the season, the driver with the most guts will cruise away in a Gold plated car as the "Hot Wheels Champion". Do you have what it takes? In Hot Wheels World Race, racing is taken to a new level as players are thrust into the unique futuristic Hot Wheels fantasy world where life revolves around the most intense stunt racing ever imagined. Players race against the clock on extreme tracks featuring split/multi-level courses, obstacles and speeds unlike anything ever experienced before.' FROM games WHERE igdb_id = 5862 ON CONFLICT (game_id, language_code) DO NOTHING;
