INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rockman-exe-4-dot-5-real-operation--1', 1769, '2004-08-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co204k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7nke.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman EXE 4.5: Real Operation', 'A Japan-exclusive Battle Network game that serves as a NetNavi simulator. Rockman.EXE 4.5 is a spin-off of the Mega Man Battle Network series. It is a simulation game where NetNavis are controlled by the AI, with the players "slotting-in" BattleChips and issuing commands. It was made to be used with the BattleChip toys and BattleChip Gate accessory, which was almost certainly the cause of the title''s Japan-exclusivity. The accessories are not required, but without them the game becomes much more difficult. The game features MegaMan.EXE, the twelve Navis that contribute DoubleSouls in Mega Man Battle Network 4, and other miscellaneous Navis. Several of the Navis in the latter category would later become playable in Battle Network 5 and 6. On the PET screen, the background music is a remix of the chosen Navi''s Classic series stage theme (if applicable).' FROM games WHERE igdb_id = 1769 ON CONFLICT (game_id, language_code) DO NOTHING;
