INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('medieval-lords-build-defend-expand', 70178, '2004-10-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ehhkyka96tkkkr7vnbse.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medieval Lords: Build, Defend, Expand', 'Medieval Lords is a 3D city-building game set in the Middle Ages. Players develop towns by constructing buildings connected by a network of roads, managing resources, and fulfilling citizens'' needs for food, security, entertainment, and religious services. The game incorporates geographical elements like water proximity and soil fertility that affect town development. Unlike traditional medieval strategy games, the combat system focuses on defensive fortifications and numerical advantage rather than tactical warfare. The game uses a zone-of-influence system where certain structures provide benefits to nearby buildings, and success depends on efficient tax collection and strategic placement of facilities to maintain population growth and unlock advanced construction options.' FROM games WHERE igdb_id = 70178 ON CONFLICT (game_id, language_code) DO NOTHING;
