INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Taisen V Episode 0: Kouya no Samurai Musume', 'Sakura Taisen V Episode 0: Kouya no Samurai Musume is a prequel to Sakura Wars: So Long, My Love starring one of that game''s heroines, Gemini Sunrise. Instead of being an SRPG/visual novel-hybrid like the other games in the series, though, Episode 0 is an action-adventure game. While riding atop her equine companion Larry, Gemini fights evil robots using Japanese sword techniques. The game features experience points and equipment systems that allow the player to upgrade Gemini and Larry''s capabilities as they see fit.' FROM games WHERE igdb_id = 74109 ON CONFLICT (game_id, language_code) DO NOTHING;
