INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pikmin 2', 'In Pikmin 2, Captain Olimar returns to the planet he was originally stranded on, to collect trinkets for his failing company to sell back at home. The game features a 2-character mechanic, which allows players to switch between two spacemen while collecting items. Two-player co-op challenge missions and a competitive mode are also available.' FROM games WHERE igdb_id = 2240 ON CONFLICT (game_id, language_code) DO NOTHING;
