INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('codename-kids-next-door-operation-soda', 49159, '2004-11-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6sat.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Codename: Kids Next Door - Operation S.O.D.A.', 'With the unanimous passing of the Soda Control Act by the Completely Unbiased We Don''t Like Kids Adult Senate, the drinking age of soda has been raised to 13 years and older. Now, you can join the Kids Next Door as they fight for children''s soda-drinking rights. Based on the animated show on Cartoon Network, this game lets you play as all five Kids Next Door operatives, each of whom has unique abilities. As you embark on this new adventure, you can use ordinary junk to create weapons and vehicles for your party.' FROM games WHERE igdb_id = 49159 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49159 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
