INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pocket-dogs', 49357, '2004-12-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7jxf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Dogs', 'In Pocket Dogs , you interact with eight different dogs in an effort to improve your human-canine relationship. You''ll be able to converse with your dog, with the dialogue changing depending on the species. You''ll also be able to make the dog play games by sharing toys with it. As the player, you''ll be able to play games for yourself via three mini games included in the title. By playing mini games players can win jewels which may be used to purchase items for their canine companion and decorate its living space. Featured breeds include the Pug, Chihuahua, and Shih Tzu. Pocket Dogs is developed in conjunction with the Hana Deka Club, a brand of toys and gifts featuring the signature cute dogs photographed with fisheye lenses.' FROM games WHERE igdb_id = 49357 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 49357 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
