INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem: The Sacred Stones', 'In Fire Emblem: The Sacred Stones, you must help protect the nation of Renais from the invading Grado Empire. Plan your strategy, choose your units, and then lead your soldiers in to battle. The more experience your soldiers gain, the more you can upgrade their abilities. This time, your soldiers can gain experience by fighting new monsters in the Tower of Valni.' FROM games WHERE igdb_id = 1440 ON CONFLICT (game_id, language_code) DO NOTHING;
