INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torn', '"Torn is a text-based online RPG set in Torn City, a dark, murky underworld where only the sharpest survive. In Torn City you can be anyone and do anything. Build your character to infinite strengths and play it your way. Torn City is a massively multiplayer game with thousands of active players around the world. Join them, attack them, befriend them, marry them, trade with them, compete with them. Whatever you do - Do it now!"' FROM games WHERE igdb_id = 94720 ON CONFLICT (game_id, language_code) DO NOTHING;
