INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('anstoss-2005', 141469, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lye.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8usa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anstoss 2005', 'In 2004, a revised version of Anstoss Edition 03/04 was published again. In addition to a new user interface, a significantly improved AI and an extended text mode, numerous other changes (e.g. an improved transfer area) have been made.  The changes were not visible at first glance, however, and so Anstoss 2005 was only considered a Kick Edition in new colors. Ascaron''s goal, however, was mainly to attract new fans for future projects.  Many ideas from Anstoss 4 were improved, but not fully developed. It is also possible here to buy a club and take over the presidency, but it is hardly possible to celebrate success here. The transfer market is also considered to be rather unrealistic, as 4 clubs always apply for a player.' FROM games WHERE igdb_id = 141469 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 141469 AND c.slug = 'ascaron' ON CONFLICT DO NOTHING;
