INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knight''s Apprentice, Memorick''s Adventures', 'Knight''s Apprentice is a third-person platformer with similarities to Jak & Daxter and Zelda games. You play as Memorick, Merlin''s apprentice sorcerer that would have preferred to be a knight, in a quest to free Avalon from Morganna, her brother Mordred and the evil Queen Maab. On your way you will meet several Knights of the Round Table, King Arthur himself, and even hold Excalibur against hordes of villains.' FROM games WHERE igdb_id = 70469 ON CONFLICT (game_id, language_code) DO NOTHING;
