INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paper Mario: The Thousand-Year Door', 'What sleeps behind the door? Time passes, the pages turn… and a new chapter unfolds in an unfamiliar land! Get ready for a two-dimensional role-playing adventure for the ages as Mario returns to paper form to discover a mystery that sleeps behind an ancient, legendary portal called the Thousand-Year Door. The quest is long, the dangers many, and this time, Mario will have to make full use of his papery qualities just to survive.' FROM games WHERE igdb_id = 3349 ON CONFLICT (game_id, language_code) DO NOTHING;
