INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('katamari-damacy', 6453, '2004-03-18', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co67mq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zkr9mepmjy8w233yhofd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Katamari Damacy', 'The King of All Cosmos accidentally destroyed the stars and—having recovered—wants the prince to rebuild them. Unfortunately the prince stands a little less than half a foot tall, so recreating the stars will require some effort. Enter the Katamari, a sphere the prince can push around our world to “roll up” items increasing the Katamari’s size until it’s suitable for the King. Taking place in stylized versions of Japanese houses, cities, and environs, the prince pushes the Katamari around collecting items which adhere to it. At first, the prince can only pick up smaller items, but as the Katamari grows, the more it can collect. Push pins and paper clips cling to the Katamari increasing its size so it can roll over obstacles and pick up bigger items. Over many levels, the Katamari can eventually pick up people, cars, and other bigger items. Players steer the Katamari from a third-person perspective using the analog sticks on the PS2. A tutorial stage takes the player through the controls and sets up the story as well as introducing a side story about a Japanese girl who can feel the cosmos. Wanting to challenge the prince, the King sets requirements on the Katamari’s size and sets time limits on the level. Bonus missions restore constellations and have their own restrictions. The world of Katamari Damacy is brought to life with off-beat animation and a catchy soundtrack. Players can find presents hidden in the levels that contain accessories for the prince. Two players can also battle head-to-head in a Katamari competition.' FROM games WHERE igdb_id = 6453 ON CONFLICT (game_id, language_code) DO NOTHING;
