INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man 2: The Snap Game', 'Spider-Man 2: The Snap Game was an online game by KFC Singapore as a part of the KFC Chicky Club, their online service of flash games for kids. The game was made to promote the movie Spider-Man 2. No copies of the game have resurfaced ever since.' FROM games WHERE igdb_id = 224660 ON CONFLICT (game_id, language_code) DO NOTHING;
