INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tanks--2', 201962, '2004-09-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa3f0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch32j.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tanks', 'Prove that you and you alone are the best tank pilot by blowing your opposition to smithereens. Play against AI opponents of varying difficulty, or challenge your friends to a duel, a duel of Tanks. Take turn launching hunks of explosive metal into the air, and then smile as then come crashing down on your opponent, obliterating terrain or the enemy tank itself. But you’ll have to make sure you have the angle just right, or the only thing you’ll be feeling—rather than a sense of victory—is embarrassment. Succeed, though, and you’ll not only get a nice sense of accomplishment for angling those attacks just right, you’ll also earn money! Spend it on upgrading your tank, or buying additional items. Keep being victorious, and you’ll be the greatest tank in all the land.' FROM games WHERE igdb_id = 201962 ON CONFLICT (game_id, language_code) DO NOTHING;
