INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pirates-the-spectacular-treasure-trail', 354720, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4fz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirates: The Spectacular Treasure Trail', 'In this PC game, children aged 6 and over can embark on an exciting treasure hunt. Who will find the treasure in the end with a compass and map? The trail of a mysterious treasure map leads to a teeming pirate island in this CD-ROM adventure! Who has enough courage and pirate cunning to take on the legacy of an old pirate captain? The future pirates are first given a detailed description of the person or flag they are looking for and also learn about piracy. With their compass, they use the cardinal points and the squares on the map to guide their search! With eagle eyes, they have to find all the secret hiding places and track down legendary sailors, because only then will the pirates get all the puzzle pieces of the treasure map they need to set off in search of the treasure with their own ship and crew. If the treasure chambers are empty, the pirates must use their skill to steal the loot from other pirates. There are also pirate-themed games, information and extras to print out in the old captain''s cabin! This adventurous pirate game requires geographical skills, a sense of direction, eagle eyes and concentration in order to shine as a proud pirate captain with a full treasure chest at the end. Players can continue their treasure hunt at any time from where they left off. The game is automatically saved under the respective name. The totally crazy treasure map is a fun and varied computer game for primary school children that teaches knowledge about the popular pirate theme in a playful way and, in particular, promotes concentration and the first use of the computer.' FROM games WHERE igdb_id = 354720 ON CONFLICT (game_id, language_code) DO NOTHING;
