INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rance VI: Collapse of Zeth', 'Rance VI -The Collapse of Zeth- is the ninth installment of the Rance Series. Despite the fact that 5D was released earlier, Rance VI is usually considered the beginning of the new Rance timeline set after Kichikuou Rance, due to the much bigger scale of the game along with the fact that it takes place in LP0004, leaving the year LP0003 where Kichikuou Rance would have taken place as "the missing year", since the canonical events of that year weren''t adapted into games. It was also from this point that many details of the lore and the setting were better established and given further detail.' FROM games WHERE igdb_id = 132656 ON CONFLICT (game_id, language_code) DO NOTHING;
