INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon Racing', 'If you thought Digimon didn''t drive cars, you''re wrong. In Digimon Racing, the Digimon crew just got their first set of wheels, and they''re ready to tear up more than 15 tracks. As your favorite Digimon character from the animated TV series, you''ll drive a kart through lava fields, jungles, and cities in a variety of game modes, including Single Race, Cup Race, Boss Challenges, and Time Trial. Link Game Boy Advance systems with a Game Link Cable for head-to-head action for up to four players.' FROM games WHERE igdb_id = 6376 ON CONFLICT (game_id, language_code) DO NOTHING;
