INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lemony Snicket''s A Series of Unfortunate Events', 'Be the Baudelaires—Switch between the 3 Baudelaire orphans to utilize each of their special abilities Invent to Prevail—Gather objects throughout your adventure to build ingenious inventions to for solving tricky puzzles or for creating unique weapons to fend off Olaf’s creepy cohorts. Truly based on a story— Engage in over 20 different missions based on the adventures from the movie and the 1st three books Dupe the dopes—Defeat Count Olaf and his troupe of villains who assume many disguises in their never-ending pursuit of the Baudelaire orphans and their family fortune.' FROM games WHERE igdb_id = 3977 ON CONFLICT (game_id, language_code) DO NOTHING;
