INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('woody-woodpecker-in-crazy-castle-5', 8012, '2004-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d73.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vq5dlikicjouuu50f4lx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Woody Woodpecker in Crazy Castle 5', 'One day Mother Nature asks for Woody Woodpeckers help. The reason? The Fairy World had been seized by demons. Woody?s interest is sparked when he learns that there is a treasure chest waiting in the legendary castle of the Fairy World. But to reach the castle Woody has to first free the five worlds of the elements of nature. The five element worlds are each separately made up of fire, water, wind, sand and wood. Each world has its own different features, its own mysterious castle, occupied by a demon that has one element key. Once Woody has gathered all five keys, the legendary Crazy Castle appears. Woody must face the same types of challenges he faced in previous five worlds as he heads toward the throne to meet the demon that occupies Crazy Castle.' FROM games WHERE igdb_id = 8012 ON CONFLICT (game_id, language_code) DO NOTHING;
