INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sacred-plus', 53570, '2004-10-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ynz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sacred Plus', 'A shadow of evil has fallen on the kingdom of Ancaria. It is a time for champions - a time to journey into the perilous world of SACRED. Battle blood-thirsty orcs & lumbering ogres... Destroy undead wizards & rotting mummies... Slay hellish demons & legendary dragons. With blazing magic & sharpened steel, prepare to embark on an epic quest of fantasy adventure & heroism. Sacred Plus incorporates all of the feedback from the player community since the first release of Sacred. This includes an optimized interface, and many completely new features: two new regions, two additional main quests, new item sets and weapons, and many new creature types which make adventuring in Ancaria even more dangerous.' FROM games WHERE igdb_id = 53570 ON CONFLICT (game_id, language_code) DO NOTHING;
