INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cube-2-sauerbraten', 21615, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hqh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6w51.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cube 2: Sauerbraten', 'Cube 2: Sauerbraten (German for "sour roast", also known as Sauer) is a cross-platform, Quake-like first-person shooter that runs on Microsoft Windows, Linux, FreeBSD and Mac OS X using OpenGL and SDL. The game features single-player and multiplayer gameplay and contains an in-game level editor. The game engine is free and open-source software, under the zlib License, with commercial support available from the developer''s own business counterpart, Dot3 Labs. The game media is released under various non-free licenses. The aim of the project is not to produce the most features and highest-quality graphics possible, but rather to allow map-editing to be done in real-time within the game, while keeping the engine source code small and elegant.' FROM games WHERE igdb_id = 21615 ON CONFLICT (game_id, language_code) DO NOTHING;
