INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man 2 Pinball', 'Spider-Man 2 Pinball is one of several mobile games based on the 2004 film Spider-Man 2. The game is an adaptation of Taito''s Trance Pinball and uses the same table layout but with new Spider-Man-themed graphics. There are two game modes: the normal mode and the score attack mode.' FROM games WHERE igdb_id = 224659 ON CONFLICT (game_id, language_code) DO NOTHING;
