INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead or Alive 2 Ultimate', 'Dead or Alive 2 Ultimate is a compilation fighting game. The compilation contains the Sega Saturn version of Dead or Alive and an enhanced remake of Dead or Alive 2 which utilized the Dead or Alive Xtreme Beach Volleyball graphics engine and offered Dead or Alive 3 game mechanics, new game content, online multiplayer capabilities and the inclusion of Hitomi as a playable character.' FROM games WHERE igdb_id = 47302 ON CONFLICT (game_id, language_code) DO NOTHING;
