INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Path', 'Follow the trail to family fun with this addictive puzzler. Arrange magic crystals in groups of three or more to remove them from the screen and clear the way. Strange creatures will try to block your way, but you''ve got wits and speed on your side. Featuring dozens of challenging levels, amazing graphics, and challenging game play, this enchanting treat from the creators of Magic Inlay and Fresco Wizard will surprise and delight adventurers of all ages.' FROM games WHERE igdb_id = 107821 ON CONFLICT (game_id, language_code) DO NOTHING;
