INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Prisoner of Azkaban: The Quest of Sir Cadogan', 'This game present on the second disc of the DVD release of Harry Potter and the Prisoner of Azkaban focuses on Sir Cadogan traveling through portraits to get to the Gryffindor Common Room to take the place of the Fat Lady as guardian of the tower, having various misadventures en route. The player must guide Sir Cadogan through the portraits by choosing between two paths at certain points, in choosing the right path will help him save time, and choosing the wrong path will result in him performing a time-wasting and usually in a comical fashion.' FROM games WHERE igdb_id = 266500 ON CONFLICT (game_id, language_code) DO NOTHING;
