INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bakufuu-slash-kizuna-arashi', 269358, '2004-11-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co75qe.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakufuu Slash! Kizuna Arashi', 'This Eye Toy game is a bit different from the rest of the pack. Included with the game is a "nail" controller which you place over your favorite finger and use to make commands in the game. Your goal as young Arashi is to bring peace back to the world by defeating an evil king. To do so you''ll take on enemies in real time battles where you use the nail controller to trace out patterns on the screen, with more complex patterns leading to more advanced attacks. To help popularize this franchise, SCE is also releasing some non-game related products for this game. A comic will appear in Japan''s popular Coro Coro Comics comic book simultaneously with the game''s release. Card decks will be released for the game and will have an effect on the gameplay experience. Placing a card in front of the EyeToy will make the game read the card and will give you access to new skills.' FROM games WHERE igdb_id = 269358 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 269358 AND p.igdb_id = 8 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('santa-claus-in-trouble-dot-dot-dot-again', 351561, '2004-12-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa1x0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxrz6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Santa Claus in Trouble... Again!', 'Santa Claus in Trouble ... again has the same premise as its predecessor: Santa Claus has lost all the presents. Now the player takes his role and has to retrieve them. This game is a standard 3D platformer, meaning the player uses his keyboard to jump through the 12 levels. He has to avoid pits and enemies. Since Santa is a peaceful guy there is no way to kill them. The basic goal of the level is to reach the exit alive. On the way the player finds the presents, for each one he collects he gets points - more challenging to get are more rewarding. There are also health boosts and reset points. But these are just temporary saves when the player dies - if all lives are lost or he ends the game he has to start all over.' FROM games WHERE igdb_id = 351561 ON CONFLICT (game_id, language_code) DO NOTHING;
