INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-nen B-Gumi Kinpachi-sensei: Densetsu no Kyoudan ni Tate!', 'During the 2004 school year at Sakura Junior High School, the famous teacher Kinpachi Sakamoto has been hospitalized. He will be unable to work for a full year so a substitute teacher is hired to teach his class while he is away. Kinpachi recommends the protagonist to take his place (an unnamed silent character) and so begins the player''s one year journey as the teacher of 3rd Year Class B.' FROM games WHERE igdb_id = 65022 ON CONFLICT (game_id, language_code) DO NOTHING;
