INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iwai Keitai Kaitsuu! Tamagotchi Plus', 'The Keitai Kaitsuu Tamagotchi Plus, usually shortened to the Keitai or K-Tama, is a Tamagotchi released in Japan on November 23, 2004. It builds on the Tamagotchi Plus, while adding new features, such as cell phone capabilities and a money system.' FROM games WHERE igdb_id = 229950 ON CONFLICT (game_id, language_code) DO NOTHING;
