INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Dead City', 'The Dead City is a short first-person point and click adventure set in the gloomy decay of a futuristic city. Polluted rain falls from the sky and runs into a river more toxin than water. As the main character, the player is trying to find the killer, but the game''s antihero soon learns that the stakes are much greater.' FROM games WHERE igdb_id = 376715 ON CONFLICT (game_id, language_code) DO NOTHING;
