INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CSI: Miami', 'CSI: Miami is a video game based on the CSI: Miami television series. The game was developed by 369 Interactive, published by Ubisoft, and was released for the Microsoft Windows on April 24, 2004. In 2008, Gameloft redeveloped the game for iOS. This game, like CSI: Crime Scene Investigation, follows a distinct pattern of five cases, with the fifth case tying together the previous four.' FROM games WHERE igdb_id = 50801 ON CONFLICT (game_id, language_code) DO NOTHING;
