INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fallout-brotherhood-of-steel', 7412, '2004-01-13', 53, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1out.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kjci6a8pc6o2xot0mhmo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout: Brotherhood of Steel', 'As a spinoff, Brotherhood of Steel''s gameplay greatly differs from that of other Fallout games. The gameplay is linear, not open-world. Instead of being able to travel freely across a broad world full of places and events as in other Fallout games, the player is confined to one location at a time. Previously visited locations cannot be visited again, and new locations can only be discovered by advancing the story. There are 50 distinct zones of varying size in Brotherhood of Steel. Brotherhood of Steel uses many of the same mechanics as other entries in the Fallout series, including the SPECIAL (Strength, Perception, Endurance, Charisma, Intelligence, Agility, Luck) attribute assignment system. These seven attributes are assigned numeric values and govern most interactions in the game. Unlike other Fallout games, however, the values are constant for each character rather than customizable. Skills exist in this game, but they do not behave like skills in other Fallout games. Rather, they are analogous to perks. When the player levels up, they receive "skill points" to increase the power of skills. Some skills also have level restrictions.' FROM games WHERE igdb_id = 7412 ON CONFLICT (game_id, language_code) DO NOTHING;
