INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GuitarFreaks 11thMix & DrumMania 10thMix', 'GuitarFreaks 11th Mix is a game in the popular GuitarFreaks series of music video games from Konami. The machine can be played by one or two players, and can also be linked with DrumMania 10th Mix. This version adds more than 30 brand new songs, for a total of over 110 songs. Gameplay remains the same from previous titles, with the player using a simulated guitar controller to play the notes of a chosen songs guitar part as they are displayed on the screen.' FROM games WHERE igdb_id = 314352 ON CONFLICT (game_id, language_code) DO NOTHING;
