INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jak 3', 'Jak 3 is a platform game developed by Naughty Dog for Sony''s PlayStation 2 console. The game is the sequel to Jak II, and third in the series. The game features new weapons and devices, new playable areas, and a storyline that picks up after the events of the previous games. As in the other games in the series, the player takes on the dual role of recurring protagonists Jak and Daxter.' FROM games WHERE igdb_id = 1530 ON CONFLICT (game_id, language_code) DO NOTHING;
