INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gambler Densetsu Tetsuya Digest', 'Gambler Densetsu Tetsuya Digest is a mahjong game from Athena. This new installment in the popular Japanese Mahjong series "Gambler Densetsu" features four different scenarios. Players have conversations with the roster of 26 characters while trying to beat them with an inventory system of cheating techniques. In addition to its large cast, the game includes three gameplay modes, a scenario battle mode, a free battle mode, and a survival battle mode. The game''s official title is Shoubushi Densetsu: Tetsuya DIGEST, but with the furigana subtitle "Gambler" for Shoubushi.' FROM games WHERE igdb_id = 332956 ON CONFLICT (game_id, language_code) DO NOTHING;
