INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sangokushi-nendaiki-dx--1', 290123, '2004-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7v0v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqzuv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sangokushi Nendaiki DX', 'A country game of the Three Kingdoms era that anyone can easily enjoy! It is an easy-to-play game set in the Three Kingdoms era of China. Focusing on territorial movement and combat, even beginners can enjoy the goal of unifying the whole country at a good tempo with simple rules. Players expand their territory while moving units to vacant territories and fighting with the opponent''s army, and if they achieve the unification of the whole country, they will win. The map reproduces the era of the Three Kingdoms in an easy-to-understand manner, and the battle is a simple operation to stop the roulette, and the one with the higher numbers wins. If the force of the unit increases, the number of roulette will increase and you can fight advantageously. Many unique warlords appear! There are also warlords with special abilities. If you win the battle, you have a chance to capture the opponent''s warlord. There are two types of scenarios, and you can choose the main character (monarch) at the start. There is also a scenario for beginners that can be cleared in 15 minutes per play. Let''s fight now to unify the world that Liu Bei and Cao Cao couldn''t do.' FROM games WHERE igdb_id = 290123 ON CONFLICT (game_id, language_code) DO NOTHING;
