INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A 3ª Jornada', 'After the destruction of Earth and Mars caused by the alien invasion, the human beings guided by Sirey are now living inside spaceships. Ten years after A 2ª Jornada, Sirey’s fleet is approaching a new solar system, where they’ll find a new planet... and new adventures.' FROM games WHERE igdb_id = 299477 ON CONFLICT (game_id, language_code) DO NOTHING;
