INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iron Sea', 'Iron Sea is a single player shooter game played from a first person perspective set during World War II. In the game the player will take command of a flagship and will refight the navel engagements of 1942, 1943 and 1944. The game offers several historical navel battles to play through and can be played on three difficulty setting : easy, normal and hard. Gameplay includes firing the ships guns and torpedoes at enemy surface ships, submarines and planes' FROM games WHERE igdb_id = 44679 ON CONFLICT (game_id, language_code) DO NOTHING;
