INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cold War Conflicts: Days in the Field 1950-1973', 'Cold War Conflicts is a real-time strategy game developed by Russian studios Fireglow Games and Red Ice software, set in the historical period of the Cold War era from 1950 to 1973. In four campaigns you take control of the military forces of eight nations (United States, Israel, Egypt, North Korea, United Kingdom, Syria, USSR and China).' FROM games WHERE igdb_id = 23785 ON CONFLICT (game_id, language_code) DO NOTHING;
