INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marine Sharpshooter II: Jungle Warfare', 'In this follow-up to the hit Marine Sharpshooter, you''ll be a lone operative fighting to restore democracy in an African country. The President of Burundi has been taken hostage by rebels and mercenaries. The brutal civil war that would ensue from this will threaten American interests - so you''ll use your elite military training and advanced weapons to take the rebels down!' FROM games WHERE igdb_id = 10537 ON CONFLICT (game_id, language_code) DO NOTHING;
