INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legend-of-zelda-four-swords-adventures', 1034, '2004-06-07', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob9xf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar220e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Four Swords Adventures', 'The Legend of Zelda: Four Swords Adventures is the only console Zelda title to date to incorporate multiplayer elements into its main campaign. Because of its single-player elements, Four Swords Adventures is also the first game in the series to allow a single player to control more than one Link at once, and it utilizes various methods to allow the player to make use of the four Links, such as formations. Also it is the only title to break locations and temples up into succinct, separate stages and levels which can be replayed even after beating them once. The game itself, though an innovation in Zelda gameplay, is heavily inspired by the music, graphics, and locations of A Link to the Past.' FROM games WHERE igdb_id = 1034 ON CONFLICT (game_id, language_code) DO NOTHING;
