INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pool-paradise', 4073, '2004-03-15', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6uec.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pool Paradise', 'Pool Paradise lets players experience playing pool in exotic locations in the South Pacific. There are 30 different computer opponents to compete against as well as 10 different table designs to play on. There are 11 different rule types to compete in and 10 different tournaments to compete in. There are five different modes to play in including Practice, Championship, Tournament, Trick Shots and a series of mini-games such as playing a game of darts on the beach, skee ball with cue balls and even shooting coconuts out of a cannon.' FROM games WHERE igdb_id = 4073 ON CONFLICT (game_id, language_code) DO NOTHING;
