INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcade Action', 'Arcade Action: 30 Games is a Miscellaneous game, developed by Mere Mortals and published by Phoenix Games, which was released in Europe in 2004. It is a compilation of thirty arcade-style games. 3D Puzzle, Airport Cargo, Barbarian Invasion, Black Box, Boa''s Maze, Bombs & Booms, Cannon Battles, Emptiness, Football Spring, Gates & Magic, Golf Master, Gravitational Attack, Helicopter Ride, Hills & Holes, Hockey, Image Maker, Mind the Numbers, One Touch, Rail Dreams, Sea Battle, Snapper, Space Rebels, Sphetrix, Steps, Stone Keeper, The Catchers, The Wall, Total Wipeout, Vacuum Cleaners, Wisdom Seekers' FROM games WHERE igdb_id = 93560 ON CONFLICT (game_id, language_code) DO NOTHING;
