INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alias', 'Alias is a third-person action adventure containing a unique blend of action and stealth that puts you under fire and under pressure. Whether you''re up against the clock or being hunted by the enemy, fighting against the odds, or fleeing for your life, the action is relentless. Utilize your incredible spyware, deadly moves, and array of disguises to complete the most dangerous covert missions across the globe. All the heart-stopping action and tension of the TV series is now under your control.' FROM games WHERE igdb_id = 5719 ON CONFLICT (game_id, language_code) DO NOTHING;
