INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Terminator 3: The Redemption', 'Terminator 3: The Redemption is a combination of 3rd person shooter, rail, and driving game featuring Arnold Schwarzenegger as the infamous T-850 Infiltrator. The game features 20+ alternate vehicles with never before seen SkyNet units and a Tech-Com Force Co-op mode. Your goal is to ensure the survival of both John Connor and Kate Brewster in present and future universes.' FROM games WHERE igdb_id = 4199 ON CONFLICT (game_id, language_code) DO NOTHING;
