INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dodgeball--1', 165568, '2004-04-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3qo5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch76t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dodgeball', 'Dodgeball is a team dodgeball game. First team to get the other team out is the winner, be it through the one-shot system or a "life system" where the object is to lower the opposition''s players health to zero. If both teams are still in by the end of the game, the team with the most players wins the game. If teams have an equal amount of players left then the team with the least damage taken wins. If equal damage has been taken by either team then the game ends in a tie.' FROM games WHERE igdb_id = 165568 ON CONFLICT (game_id, language_code) DO NOTHING;
