INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('maribato', 234649, '2004-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co631g.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maribato!', 'Maribato! is a fanmade Fighting Game developed in 2004 for the PC by DK Software, and has the most popular characters of Maria-sama ga Miteru as playable characters. Gameplay is similar to that found in other games such as Street Fighter, The King Of Fighters, Guilty Gear, among others, and the characters sport quirky yet very funny and lovely moves and styles that can be traced to those games; It also includes in-jokes and references to the Light Novel. The stages are based in actual locations at Lillian Academy, and the characters are presented using a Super Deformed style for their sprites. The game consists in matches of 2 best out of 3 rounds between two teams of two soeurs each, and follows a Tag Team structure, similar to games like Marvel Vs. Capcom, and allows to switch characters at any time, useful to extend combos, or to escape an enemy combo. However, if one character''s life meter is depleted, the team automatically loses one round. A second version of the game, called Maribato! Version 2.0 was released in Comiket 70 in 2005, and a third one, called Maribato! Plus, was released one year later, both presented as standalone discs. Both version add new characters and stages, and rebalance the existing ones.' FROM games WHERE igdb_id = 234649 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 234649 AND c.slug = 'dk-software' ON CONFLICT DO NOTHING;
