INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('scooby-doo-castle-capers', 376522, '2004-03-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coavgc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc108lr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo!: Castle Capers', 'Scooby-Doo!: Castle Capers is a puzzle adventure game starring Scooby and Shaggy from the cartoon series. The gang''s car broke down and they had to stop at a mansion that turned out to be haunted. It''s now their job to investigate the mansion and find out what is really going on. The mansion acts as a level select area and the place where most of the conversation between the gang and the characters in the mansion occurs. After clearing a level, the next door is unlocked and players can go there. Players can''t replay the levels they''ve already cleared. In the levels, players have a time limit to find a clue and leave the level through the entrance. Players can switch between Scooby and Shaggy at any time and will need to use both characters to open paths for each other and solve the puzzles of the levels. Although the game has hearts in the top left corner of the screen, both Scooby and Shaggy lose one heart if the enemy touches them and have to start the level from the beginning.' FROM games WHERE igdb_id = 376522 ON CONFLICT (game_id, language_code) DO NOTHING;
