INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moon Minions', 'Moon Minions is a currently lost old Scott Cawthon game released in 2004. some information we know from old Daily Click reviews and articles, we know the game was about a RPG where you can take control of a moonman and his minions on a robot infested planet and must try and destroy a interstellar dark energy called the "Phantom Core".' FROM games WHERE igdb_id = 243940 ON CONFLICT (game_id, language_code) DO NOTHING;
