INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joint Operations: Typhoon Rising', 'Joint Operations is a First Person Shooter, totally focused on online multiplayer mode. The game is set in Indonesia in an hypothetic near future, where a national separatist movement (Rebels) fight against the international pacification force (Joint Operations), and features many tropical locations, characterized by jungle, marshes and archipelagos. The game has five multiplayer modes (Coop, Andavence and Secure, King of the Hill, Deatmmatch and Team Deathmatch), 5 character classes (Rifleman, Gunner, Engineer, Sniper and Medic) and can host up to 150 players in each game.' FROM games WHERE igdb_id = 9354 ON CONFLICT (game_id, language_code) DO NOTHING;
