INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-nightmare-before-christmas-oogie-s-revenge', 6200, '2004-10-21', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rn4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctf5v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Nightmare Before Christmas: Oogie''s Revenge', 'Action game based on Henry Selick''s stop-motion movie masterpiece. Players slip into the role of Jack Skellington, King of Halloween, and relive the adventures set in Tim Burton''s dark world. Following the events of the Tim Burton''s The Nightmare Before Christmas movie, players take control of Jack Skellington who sets out on a search of new ways to spook kids during Halloween. He returns home to find that Oogie Boogie has returned and Halloween Town is in peril once again. The game combines elements of action, platforming, and rhythm-based gameplay, as Jack must also perform musical battles to defeat certain bosses and progress through the story. Each battle is set to a unique musical number, bringing the dark charm of the film''s soundtrack to life in a new and interactive way.' FROM games WHERE igdb_id = 6200 ON CONFLICT (game_id, language_code) DO NOTHING;
