INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vic de Vitaminevreter', 'Step into the colorful world of Vic, a cheerful little creature with an insatiable hunger for vitamins! In this exciting and educational platform game, you’ll travel through various worlds — from the Vegetable Forest to the Fruittopia Island — in search of healthy snacks and hidden superfoods. But watch out: cotton candy spiders, fat monsters, and soda snakes are lurking around!' FROM games WHERE igdb_id = 349776 ON CONFLICT (game_id, language_code) DO NOTHING;
