INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Net de Bomberman', 'Bomberman, which continues to attract many fans with its simple gameplay, has finally become a network battle! Moreover, it is possible to play up to 8 players this time! If you connect to the net, you can have a heated battle not only with your usual friends but also with many rivals on the other side of the net!' FROM games WHERE igdb_id = 77673 ON CONFLICT (game_id, language_code) DO NOTHING;
