INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-lord-of-the-rings-the-battle-for-middle-earth', 3154, '2004-12-06', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20og.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5gh6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lord of the Rings: The Battle for Middle-earth', 'The players control the heroes or villians from the famous Lord of The Rings movies. With a hero characters similar to the Warcraft series you control both the armies and all the unique heroes. The game follows the movies very closely and even got scenes from the films appear in game. Not only does the game contain a giant campaign where you play through the journey of the ring as the good side, the game also features an evil campaign where as the players play as the evil forces of Middle Earth. With multiple diffrent races from all over Middle Earth, a giant spell tree to customize your game and a unique basebuilding layout the game was great for its time.' FROM games WHERE igdb_id = 3154 ON CONFLICT (game_id, language_code) DO NOTHING;
