INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman EXE Phantom of Network', 'Rockman EXE Phantom of Network is a video game in the Mega Man Battle Network series for mobile phones developed by Capcom. The game was only released and made available in Japan. It is most well known for featuring five original characters that did not appear in any other video games: the magician Mr. Hat with his NetNavi HatMan and son Shuichi Ubochi as well as the NetNavis JammingMan and Cache. All of these characters, however, appeared in the Rockman EXE anime series. The game was followed by a Japan-exclusive sequel for mobile phones entitled Rockman EXE Legend of Network.' FROM games WHERE igdb_id = 265957 ON CONFLICT (game_id, language_code) DO NOTHING;
