INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('this-is-football-2004', 44674, '2004-03-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wzi.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Is Football 2004', 'If there''s one thing you can''t fault This Is Football 2004 on, it''s scope. While other PlayStation 2 football titles are happy to concentrate on national and international teams, here the beautiful game is taken right down to grass roots, allowing you (if you wish) to seize control of a local team. You do that as part of the best feature in the game: the career mode. Here, you really can go from the very bottom to the very top, and it adds a challenging long term goal to the proceedings. It''s just one example of where the game differs from the opposition, and there are plenty more. For instance, you can also try and blatantly blag a penalty by diving in the area. You can get penalised for handball. You can even take it online and test your skills. In short, there''s plenty going on.' FROM games WHERE igdb_id = 44674 ON CONFLICT (game_id, language_code) DO NOTHING;
