INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Warcraft: Collector''s Edition', 'When World of Warcraft was released for sale, it came as a regular version (basically the game manual and some game CDs) and a special Collector''s Edition. The Collector''s Edition includes: - Large, hard-sided slip-out box with fitted fuzzy holder for all the contents. - The full game on CD-ROM and DVD-ROM. - "Behind the Scenes" DVD with the game''s cut-scenes, 3D concept art, drawings, screen shots, and audio tracks of Blizzard employees discussing in-depth the various elements of the game. - 280-page hardcover coffee table book, The Art of World of Warcraft. - World of Warcraft Soundtrack CD. - Cloth gameworld map with a metal clasp. - Exclusive in-game pet for every character. Choice of Zergling, Panda Cub, or Mini Diablo. - 10-days free for a friend (via voucher with special CD-key). - The game manual. - Blizzard Store pamphlet!' FROM games WHERE igdb_id = 136994 ON CONFLICT (game_id, language_code) DO NOTHING;
