INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hannah and the Ice Caves', 'Hannah and the Ice Caves is the second in the trilogy of Hannah the Brave games. Following her exploits in the Pirate Caves and coinciding with a sitewide plot event, Hannah is joined by Armin of the newly introduced Bori race. Together, they must combine their unique abilities to clear a path and reach the exit.' FROM games WHERE igdb_id = 338367 ON CONFLICT (game_id, language_code) DO NOTHING;
