INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Going Baseball - Kaizoku Yakyuu', 'One Piece: Going Baseball is a Japanese only game released for the GameBoy Advance in 2004. The controls are simple and the basic point of the game is to choose a team and try to win in a tournament against all the other teams. There is a story mode, which is needed to unlock the final team, and a minigame mode. The game appears to take place after the Skypiea Arc, as the crew is seen in the beginning wearing their outfits from Skypiea, and the Skypiea arena is the farthest point that the game goes up to.' FROM games WHERE igdb_id = 49736 ON CONFLICT (game_id, language_code) DO NOTHING;
