INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ground-control-ii-operation-exodus', 735, '2004-06-18', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28md.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpi7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ground Control II: Operation Exodus', 'Like the original, Ground Control II is not a standard base-building RTS game. There is no technical upgrade tree, and no mining for gold, crystals, or any other random mineral to be used as a monetary source. New units are acquired by spending acquisition points which collect throughout the battle. If the player has a large force, the points will come in very slowly. While the army is small, the points will come in at faster rate. More points can be earned by destroying enemy units, or by capturing special locations called victory locations. Additional units are called in via dropship, which will land in designated landing zones. The player must hold at least one of these landing zones in order to receive these reinforcements. Acquisition points can also be spent on dropship upgrades which include more cargo space, speed, fuel capacity, armor, and weapons.' FROM games WHERE igdb_id = 735 ON CONFLICT (game_id, language_code) DO NOTHING;
