INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('outrun-2-sp-special-tours', 43566, '2004-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oy6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3foz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OutRun 2 SP: Special Tours', 'This is an upgrade version of Outrun 2 with 15 all-new courses which are predominantly based around a New World theme. In Outrun 2 - Special Tours Sega adds a number of new features that will challenge and entertain players of all skill levels including: -15 new exhilarating courses for a total of 30! The new courses are based on highways and byways of the US. You''ll recognize skylines and vistas of major cities and highways from across the country! -2 new Ferrari''s - The 512BB and 250GTO. This gives players a choice of 10 of the world''s greatest sports cars to race with! -Players of any skill level will feel the thrill of competing like never before thanks to Sega''s Re-tuned Artifical Intelligence. The enhanced AI will help novice drivers stay in the race until the very end resulting in increased enjoyment for all! -New Background Music. 7 tunes from the original OutRun and Turbo OutRun have been added that''ll bring back fond memories.' FROM games WHERE igdb_id = 43566 ON CONFLICT (game_id, language_code) DO NOTHING;
