INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ricochet Lost Worlds: Recharged', 'The award-winning game play of Ricochet Lost Worlds is back! From the talented minds of designers all over the world comes the most dynamic brick-busting experience ever! This wild and warped game has you smashing your way through over 350 beautiful and exhilarating rounds that are truly the best of the best. With its gorgeous artwork and innovative "Ring Game", you need to download it today. Rejuvenated, Reloaded...RECHARGED!' FROM games WHERE igdb_id = 79393 ON CONFLICT (game_id, language_code) DO NOTHING;
