INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men Legends', 'X-Men enter the realm of role-playing games with an intense story, superhero action, and multiplayer modes. The story in X-Men Legends begins when the X-Men learn that Magneto has devised a plan to give mutants the power to reign supreme over humans. To save the human race from imprisonment, you compose a four-person team from a roster of X-Men characters, including Storm, Gambit, and Wolverine.' FROM games WHERE igdb_id = 4575 ON CONFLICT (game_id, language_code) DO NOTHING;
