INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knuckles Baseball', 'Knuckles Baseball is an LCD game created for distribution at McDonald''s restaurants. They were offered as a part of Happy Meals for a limited time in 2004. Strangely this game seems to have not been released in all regions of the world and a totally different Knuckles themed game was released elsewhere. The objective of the game is to catch baseballs thrown by Sonic. This is done by pressing the button at the correct time after the ball is thrown. If ten are caught the game will advance by 1 level and the speed of the game will increase.' FROM games WHERE igdb_id = 198600 ON CONFLICT (game_id, language_code) DO NOTHING;
