INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadly Strike', 'Enter the toughest combat tournament on Earth as one of six lethal fighters. Using a mixture of powerful martial arts techniques, swordplay and good old-fashioned hot lead you must battle through the beautiful scenery of the Shogun''s Island. Defeat hundreds of the enemy''s evil minions in your struggle to reach his castle and claim victory over the other contestants.' FROM games WHERE igdb_id = 43604 ON CONFLICT (game_id, language_code) DO NOTHING;
