INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sky Force', 'Pick one of three ships and blast your way to victory in this ultimate classic arcade shooter! Sky Force brings you pure blasting action in 8 immersive levels filled with vicious enemies, big bosses, destructible objects and the good old Earth to save! Use various explosive weapons, useful power-ups, and unlockables such as heat-seeking missiles or the amazingly powerful laser attack! Sky Force is a breathtaking and action packed top-down scrolling shoot‘em up which delivers fun and addictive gameplay that will keep you entertained for hours! Get this game now and stand up against the enemy - the Earth deserves its new hero!' FROM games WHERE igdb_id = 77475 ON CONFLICT (game_id, language_code) DO NOTHING;
