INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla: Save the Earth', 'Godzilla: Save the Earth is a fighting video game released in 2004 for the PlayStation 2. It was the first Godzilla title to be released for both the PlayStation 2 and Xbox game consoles. Based on characters and situations from the Godzilla film series, the game itself is the sequel to Godzilla: Destroy All Monsters Melee, released for the GameCube and Xbox in 2002. Godzilla: Save the Earth is followed by Godzilla: Unleashed in 2007 for the PlayStation 2 and the Wii.' FROM games WHERE igdb_id = 5847 ON CONFLICT (game_id, language_code) DO NOTHING;
