INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Audition Online', 'Audition Online, is a downloadable multiplayer online casual rhythm game produced by T3 Entertainment. It was originally released in South Korea in 2004, but it has been localized by various publishers around the world. Audition Online is free to play but it earns its revenue by selling virtual items such as clothes for the player''s avatar. It is a major hit in Indonesia and Vietnam.' FROM games WHERE igdb_id = 9555 ON CONFLICT (game_id, language_code) DO NOTHING;
