INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maniac Mansion Deluxe', 'Maniac Mansion Deluxe is a 1:1 remake of the original "Maniac Mansion" on 256-colour. Sandy, girlfriend of the games'' hero Dave has been kidnapped by evil scientist Dr. Fred Edison. So Dave has to gather two friends around him and go to the old mansion to rescue her.' FROM games WHERE igdb_id = 198173 ON CONFLICT (game_id, language_code) DO NOTHING;
