INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atlantis: Evolution', 'Atlantis: Evolution is the fourth title in the Atlantis series started by Cryo, and the first one made by Atlantis Interactive Entertainment, founded by former Cryo developers. Unlike the second and the third game in the series, the game revolves entirely around a newly built Atlantis. It was followed by The Secrets of Atlantis: The Sacred Legacy in 2006.' FROM games WHERE igdb_id = 19446 ON CONFLICT (game_id, language_code) DO NOTHING;
