INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Wrestling 2: There Goes the Neighborhood', 'Backyard Wrestling 2: There Goes the Neighborhood is the second installment in the Backyard Wrestling series and was released on Xbox and PlayStation 2. The licensed soundtrack includes music by Andrew W.K., Kool Keith, the Insane Clown Posse, Bad Brains, Body Count, Six and Violence, Mudvayne, Saliva, Fall Out Boy, and Hoobastank. It was developed by Paradox Development, now owned by Midway Games, and was published by Eidos Interactive. The television commercial included Insane Clown Posse, Vampiro, New Jack, and Major Gunns. Despite promises of an improved gameplay experience, the game was a critical flop when released in 2004. Its sales numbers remained respectable, however, moving nearly 300,000 copies through 2005.' FROM games WHERE igdb_id = 5735 ON CONFLICT (game_id, language_code) DO NOTHING;
