INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daigasso! Band Brothers', 'Daigasso! Band Brothers is a music video game published and developed by Nintendo as a launch game for the Nintendo DS. It features multiple songs, which include classical music, television themes, and video game music. The game is controlled using both the buttons on the DS as well as its touch screen in certain portions. It uses a variety of different instruments, which are combined selectively in order to compose a song. Besides the primary mode, players may play together, each one playing a different instrument in the song. Players may also compose their own songs.' FROM games WHERE igdb_id = 28559 ON CONFLICT (game_id, language_code) DO NOTHING;
