INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trigger Man', 'Trigger Man puts you in the shoes of the Underworld''s toughest Mob enforcer. To survive all you''ll have are your wits, muscle and street-smarts. Eight challenging missions in which to destroy the operations and soldiers of the rival families. Hunt out your opponents in realistic locations including deserted loading docks, fine restaurants and a casino.' FROM games WHERE igdb_id = 4210 ON CONFLICT (game_id, language_code) DO NOTHING;
