INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alloy: Arena', 'Alloy: Arena is a game created by MindChamber and PsychoGoldfish. The minigame consists of using combos of guns, punches, and kicks to kill the gang known as "Da ''Hood Rats" and also the robotic cyber-dogs called "Cyber Pit Bulls." The game has over 3 million views and features in the Flash Portal History 2004 Collection.' FROM games WHERE igdb_id = 318136 ON CONFLICT (game_id, language_code) DO NOTHING;
