INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'InuYasha: Demon Tournament', 'InuYasha Demon Tournament is a RPG strategy game featuring the characters from InuYasha. Participate in the demon tournament to win the shikon jewel, which is a powerful artifact that will grant great power to whomever attain it. Gather all the shards of the shikon jewel by defeating each opponents. You must use your courage and strategy to outwit your enemies on the battlefield, or the jewel will be lost for you.' FROM games WHERE igdb_id = 185829 ON CONFLICT (game_id, language_code) DO NOTHING;
