INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chaos-field', 124006, '2004-05-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yvi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm6xo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Field', 'Chaos Field is a top-down space shooter similar in concept to the Gradius series, or Ikaruga. You control one of three ships, each with their own pilot and unique weapon systems. The game takes place over 5 phases, in each phase you face a number of boss battles. Unlike other games if this genre, almost the entire game is composed of boss battles, each boss requiring a different strategy to defeat. The game also uses a unique in-game difficulty adjuster. Called "fields", you can play in either Order or Chaos. Compared to Order, the Chaos Field offers you increased fire power and abilities, but also does the same for your enemies. Order Field is more relaxed on both sides. If you can play in the Chaos Field, you stand to gain substantially more points.' FROM games WHERE igdb_id = 124006 ON CONFLICT (game_id, language_code) DO NOTHING;
