INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-wombat', 346213, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9vw8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scx2co.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Wombat', 'Space Wombat is a 3D platformer that follows the adventures of the eponymous spacesuit-wearing bipedal wombat. Space Wombat is heading home to Planet Ucliptus when his spaceship receives a distress call from a nearby planet. While landing to investigate, Space Wombat damages his ship; to make matters worse, his cargo—a shipment of the valuable Power Gumnuts—is seized by the evil WomBots, whose ploy it was to lure him to their base. Now, Space Wombat must recover his stolen cargo, repair his ship, and escape. Gameplay mostly consists of collecting Power Gumnuts while jumping on crates, avoiding obstacles, and dealing with WomBots, some of which can be destroyed while others can only be temporarily disabled. There is a boss fight after every five levels, as well as a bonus level that can be unlocked by collecting the letters "W," "O," "M," "B," "A," and "T," which are strewn around the levels. Running on Macromedia Shockwave, Space Wombat was originally released as an ad-supported browser-playable game, but was later made available as a paid downloadable version.' FROM games WHERE igdb_id = 346213 ON CONFLICT (game_id, language_code) DO NOTHING;
