INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('baldur-s-gate-dark-alliance-ii', 84, '2004-01-20', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tb2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cxn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baldur''s Gate: Dark Alliance II', 'Using the 3rd Edition Dungeons & Dragons rules set, Baldur''s Gate: Dark Alliance II features four new acts of hack-and-slash combat and powerful spell casting. Even more monster types will engage in real-time battles using the same overhead perspective as witnessed in the original game. Each selected character can parlay the experience gained from combat into acquiring new feats and enhanced abilities over time. To help in battle, a new item creation system lets players craft magical weapons and armor using raw materials found during their travels. As before, two heroes can join the adventure in cooperative play on the same screen, with each character differing in the types of feats and powers under his or her command. Equipment can be found or purchased from local merchants using the gold looted from felled creatures or received as payment for quests. Baldur''s Gate: Dark Alliance II also features a number of hidden areas, secret characters, and literally hundreds of items to find and use, including potions, scrolls, and wands. In addition, the game features a new branching storyline that offers players a choice where to go next for fortune and honor.' FROM games WHERE igdb_id = 84 ON CONFLICT (game_id, language_code) DO NOTHING;
