INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ankabar', 'Akanbar is a text-based online Role Playing Game, a land of magic, mystery and fantasy where you the player help to weave the ever changing storyline. Akanbar is an online fantasy role playing game created by a team of developers who have spent much of their lives both playing and creating role playing worlds. What we have aimed to create is the best of the best. A land that is constantly evolving and cared for by its creators.' FROM games WHERE igdb_id = 228878 ON CONFLICT (game_id, language_code) DO NOTHING;
