INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA Football 2005', 'NCAA Football 2005 is an American college football video game which was released on July 15, 2004. It is the successor to NCAA Football 2004 in the NCAA Football series. The product features former Pittsburgh Panthers and current Arizona Cardinals standout wide receiver Larry Fitzgerald on the cover. The game is the NCAA Football series released by EA Sports. This would be the final game in the NCAA Football series to be released on the Nintendo Gamecube.' FROM games WHERE igdb_id = 5957 ON CONFLICT (game_id, language_code) DO NOTHING;
