INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-aladdin-chess-adventures', 78216, '2004-10-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vyn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7hwx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Aladdin: Chess Adventures', 'Disney''s Aladdin Chess Adventure is a puzzle game that uses and teaches chess to beginning chess aficionados. The player navigates through the world of Disney''s Aladdin helping Aladdin and his friends on story-based quests. The player encounters characters, creatures and obstacles along the way and must gather up an army of chess pieces and magic items in order to progress. By successfully completing different chess challenges, mini-games, chess puzzles and tutorials, the player grows his chess army, gathers gold and collects magic items. The quests get progressively more difficult and new chess concepts are folded into the storyline. Players do not need any prior chess knowledge to play - the game teaches the rules as players progress.' FROM games WHERE igdb_id = 78216 ON CONFLICT (game_id, language_code) DO NOTHING;
