INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Granny', 'Super Granny is an action/puzzle video game developed by Sandlot Games and published by WildTangent for Windows. Players control Super Granny, who can use her shovel to dig holes, and go on a quest to rescue her missing kitties from evil gnomes set on conquering the world.' FROM games WHERE igdb_id = 7502 ON CONFLICT (game_id, language_code) DO NOTHING;
