INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby & the Amazing Mirror', 'Once again, Kirby must save the kingdom from evil. But this time he''ll need some backup. As Kirby, you can call up one of four alter egos for help during your quest. Each character features new copy abilities that range from arrow-shooting to melee moves. Practice your skills in new side games, such as Crackity Hack and Speed Eaters. In addition to new abilities and subgames, Kirby & the Amazing Mirror also introduces new multiplayer modes.' FROM games WHERE igdb_id = 3721 ON CONFLICT (game_id, language_code) DO NOTHING;
