INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chronicles of Riddick: Escape from Butcher Bay', 'Escape from Butcher Bay is set in the futuristic science fiction universe of the Chronicles of Riddick franchise, and is a prequel to the film Pitch Black. The game takes place inside Butcher Bay, a maximum-security prison from which no prisoner has escaped. The facility - constructed on a barren planet - contains three increasingly secure holding areas, and a subterranean mining operation.' FROM games WHERE igdb_id = 250 ON CONFLICT (game_id, language_code) DO NOTHING;
