INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Vault', 'While the future is doomed, there may be hope for man in the past, but when a band of fighters travel back to 1958, the mutant government army follows. Facing superior numbers and technology, with the threat of nuclear war hanging over their heads, and no way to return home, it''s up to the player to fight through 20 levels to survive.' FROM games WHERE igdb_id = 71963 ON CONFLICT (game_id, language_code) DO NOTHING;
