INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kappa no Kai-kata: How to Breed Kappas', 'Konami''s PlayStation 2 Kappa adventure game, based on the TV anime of the same name. The story takes places in Showa 40 and follows the story of a young boy named Hiroshi, who''s forced to spend his summer at his grandparent''s house. Hiroshi''s grandparents have these green, prank-prone creatures called Kappas, and you earn your keep by raising them -- teaching them manners, guiding them and so-forth.' FROM games WHERE igdb_id = 335977 ON CONFLICT (game_id, language_code) DO NOTHING;
