INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man X8', 'Mega Man X 8 adds more depth and variety to this classic gaming series. With Earth in ruins after Sigma''s invasion, humanity builds a new kind of reploid to colonize the moon. Sigma has corrupted their DNA and made them turn on humans. You and your teammates head to the moon for outer-space adventure of epic proportions!' FROM games WHERE igdb_id = 1748 ON CONFLICT (game_id, language_code) DO NOTHING;
