INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-war-ii-sniper-call-to-victory', 138090, '2004-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5djy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scj0wx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World War II: Sniper - Call to Victory', 'World War II: Sniper - Call to Victory is the third title from Jarhead to place the player in the role of an American military sniper (the first two being their Marine Sharpshooter games). This time, the player takes on the role of an Airborne soldier in 1944 as the Allies are beginning the liberation of Europe. The ten mission campaign takes place around three major engagements: Operation Market Garden, the battle of the Bulge, and the battle for the bridge at Remagen. The game uses the LithTech Jupiter engine and the same basic mechanics of the Marine Sniper games, although the emphasis is more on action and less on stealth. There are a few rail style vehicle missions and the player usually operates without an A.I. sidekick (although some missions include protecting and providing cover fire for friendly soldiers). Most of the time, the weapon of choice for eliminating enemies is the Springfield M1903 Sniper Rifle, but there are a few additional choices available for when things get hairy including Thompson submachine guns, grenades and bazookas.' FROM games WHERE igdb_id = 138090 ON CONFLICT (game_id, language_code) DO NOTHING;
