INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-egyptian-prophecy-the-fate-of-ramses', 17414, '2004-03-29', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jzu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnuk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Egyptian Prophecy: The Fate of Ramses', 'Plunge into ancient Egypt and follow Maya, a young magician, who has been ordered by Pharaoh to investigate the strange accidents that have recently occurred at the great obelisk''s worksite. Find out what is standing in the way of your sovereign''s mission. Evade curses and spells, and allow your people to construct one of the great architectural splendors of antiquity to the god Amon-Ra. A point-and-click adventure game using 360° views, similar to Jules Verne''s Return to Mysterious Island and Dracula: The Path of the Dragon.' FROM games WHERE igdb_id = 17414 ON CONFLICT (game_id, language_code) DO NOTHING;
