INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rumble Roses', 'Get ready for sexy yet challenging in-the-ring combat. WWX: Rumble Rose delivers intense girl-on-girl wrestling action with an all-female roster of vixens--each with specialty moves. The combat system lets you humiliate your opponents through insults, taunting, and aggressive moves and holds. Your player''s costume, attitude, and wrestling style change depending on whether you fight dirty or fair. Naughty or nice, becoming a popular wrestler will earn benefits, including expanded gameplay, additional skills and moves, and more-revealing and flamboyant costumes.' FROM games WHERE igdb_id = 27041 ON CONFLICT (game_id, language_code) DO NOTHING;
