INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('t-raumschiff-surprise-periode-1', 131283, '2004-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobca6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc11fsm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '(T)Raumschiff Surprise - Periode 1', 'The license for this game was acquired from the German blockbuster comedy of the same title by a very popular German comedian called Michael "Bully" Herbig. The movie is parody on SF series/movies like Star Trek and Star Wars. The story of this point-and-click adventure is close to the movie''s plot: the player consecutively takes over the roles of Captain Kork, Mr. Spuck and Schrotty and has to solve many riddles and tasks such as activating the spaceship''s own musicbox so that the crew can practice for the "Miss Waikiki" dancing contest. The main story features some mini games like dancing. The characters are controlled by mouse only, using the left mouse button to move the character to the indicated places, start dialogues with other characters or use items. If an item or a person is clicked with the right mouse button, a context menu with the respective information appears.The actors have given the game characters their voices and have recorded over 1600 different spoken sequences.' FROM games WHERE igdb_id = 131283 ON CONFLICT (game_id, language_code) DO NOTHING;
