INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Under Fire: The Crusaders', 'Kingdom Under Fire: The Crusaders is a tactical wargame developed by the Korean studio Phantagram for the Xbox. It is the sequel to the 2001 game Kingdom Under Fire: A War of Heroes, and continues its storyline. Kingdom Under Fire: The Crusaders combines third-person action and role-playing elements in its gameplay, which differs from its predecessor. Its sequel is Kingdom Under Fire: Heroes. Another sequel is to be released in 2015 entitled Kingdom Under Fire II for PC and PlayStation 4.' FROM games WHERE igdb_id = 5883 ON CONFLICT (game_id, language_code) DO NOTHING;
