INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WingNuts: Temporal Navigator', 'A classic birds-eye view arcade shooter where the player controls a selection of airplanes from WW2 propeller planes with machine-guns to futuristic jets with energy weapons, bombs and missiles. The goal is to blow up pretty much everything (planes, tanks, ground structures, blimps and the occasional boss) while chasing the evil Baron von Schtopwatch through time-warps across a storyline laid out in short comic-style cutscenes.' FROM games WHERE igdb_id = 201073 ON CONFLICT (game_id, language_code) DO NOTHING;
