INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mvp-baseball-2004', 10627, '2004-03-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7l5h.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MVP Baseball 2004', 'EA takes its MVP Baseball franchise to the next level in 2004. Features realistic player models, historic ballparks and players, full EA Sports Bio compatibility, and an enhanced franchise mode. The all-new Advanced Hitting Control lets you place the bat where you want it. Control the field as you leap over the wall to rob home runs, hook slide into 3rd or barrel over the catcher at home. Manage your team—from the minors to the pros—and take your ball club to win the World Series! Groundbreaking hitting control makes it possible to pull the ball down, or swing for the fences -- all swing types included Total control on the field - Leap over the wall and rob home runs, hook slide to avoid tags, and take out the catcher at home Pick a park - each stadium has its own personality, from unique crowd chants to personal lighting Control your franchise on every level -- play the game or become a manager & take players from the minors to the pros' FROM games WHERE igdb_id = 10627 ON CONFLICT (game_id, language_code) DO NOTHING;
