INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skools Out', 'Skools Out is an educational adventure game for younger players. The main character, a boy named Derek, must try within twenty days to make sure that the sheet of paper with the latest results of his scientific achievements does not reach home. The notes there are not among the highest, so it would be better not to get them in the hands of parents.' FROM games WHERE igdb_id = 338809 ON CONFLICT (game_id, language_code) DO NOTHING;
