INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Before Crisis: Final Fantasy VII', 'Before Crisis: Final Fantasy VII is a Japanese action role-playing game developed and published by Square Enix in 2004. It is the prequel to Final Fantasy VII, taking place during the six years prior to it. Before Crisis was the first original (i.e. not an enhanced remake) game Square Enix produced for mobile phones.' FROM games WHERE igdb_id = 80033 ON CONFLICT (game_id, language_code) DO NOTHING;
