INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biohazard The Stories', 'Biohazard The Stories is a mobile phone game based on Resident Evil 3: Nemesis. THE STORIES was first released on docomo phones in 2004, followed by au and SoftBank phones in 2005 and 2007, respectively. It is the sequel to Resident Evil: The Missions. The game was never released outside of Japan and was followed by a sequel, BIOHAZARD the episodes.' FROM games WHERE igdb_id = 356245 ON CONFLICT (game_id, language_code) DO NOTHING;
