INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Driv3r', 'In the game you take the role of Tanner, the undercover cop from previous Driver games, as he infiltrates a worldwide high-performance car theft ring. Nothing is too dangerous or too risky for Tanner, and you''ll be able to hop into any car, truck, or motorcycle and cruise the streets of three re-created cities with over 156 miles of roads, from Miami, Nice, and Istanbul in over 25 storyline missions. Meet up with characters from previous driver games, the story line lives on in this installment.' FROM games WHERE igdb_id = 5817 ON CONFLICT (game_id, language_code) DO NOTHING;
