INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yetisports', 11835, '2004-01-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bsr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/c3u08gkq1xcevipsujrj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yetisports', 'Yetisports (also known as Pingu Throw) is a web-based Flash game that originally appeared on the Internet in January 2004. The goal of the original game is to have a yeti smack a penguin with a club and try to get it to fly as far as possible. The original Yetisports game features no name other than the words "1978 Reinhold + Yeti", a reference to Reinhold Messner''s claim to have found Yetis. The game is very popular and soon after release, there was a quick succession of many variants created by multiple people on the internet. None of these are officially sponsored by Chris Hilgert, even though many copy the original almost exactly save certain small changes. One of the more violent variants was made by someone known as ''Pawel'', featuring decapitation, spikes, a big spiky club and mines. Since the original was released at the Yetisports homepage, the website has released nine further adventures of the Yeti as well as a re-release of the original that allows movement of the penguin in flight.' FROM games WHERE igdb_id = 11835 ON CONFLICT (game_id, language_code) DO NOTHING;
