INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Duty: Finest Hour', '"Call of Duty: Finest Hour" is an immersive first-person shooter set against the dramatic backdrop of World War II. Developed by Spark Unlimited and published by Activision, this installment transports players to the heart of historic battles across multiple fronts. Experience the intensity of warfare through the eyes of American, British, and Soviet soldiers, each with unique missions and storylines.' FROM games WHERE igdb_id = 3761 ON CONFLICT (game_id, language_code) DO NOTHING;
