INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-lord-of-the-rings-the-third-age', 6500, '2004-11-02', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20oe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mn2l46t3dfbhmr2vbnkj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lord of the Rings: The Third Age', 'The Lord of the Rings:The Third Age introduces entirely new characters which aren''t mentioned in the books or movies. The game does relate to the movies by including scenes from all three movies, with new background speech by Ian McKellen (Gandalf). There are seven playable characters in the game which have been created specifically for it, as well a small appearances by characters such as Gandalf, Aragorn, Eowyn, Faramir, and Gothmog. The game covers events in all three movies/books, mostly with references to major events shown through cut scenes, or the scenes from the movies with Ian McKellan''s narration. A classic RPG game, The Lord of the Rings: The Third Age has gameplay elements similar to Final Fantasy, where you have a party of characters, each with a different set of skills and attributes, who gain levels, making them stronger as the game progresses. Battles are turn-based, and let the gamer make different decisions on what they want to do to change the outcome of the battle. The game travels through many areas throughout Tolkien''s Middle Earth, including The Pelennor Fields and Moria.' FROM games WHERE igdb_id = 6500 ON CONFLICT (game_id, language_code) DO NOTHING;
