INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom Fighting Evolution', 'Capcom Fighting Jam, released in the US as Capcom Fighting Evolution, is a 2004 head-to-head fighting game from Capcom. It was originally released as a coin-operated arcade game for the Namco System 246 hardware and ported to the PlayStation 2 and Xbox. The game features characters from three different incarnations of the Street Fighter series, as well as characters from the Darkstalkers series and the CPS III arcade game Red Earth, with each character employing the fighting system from the game which they represent.' FROM games WHERE igdb_id = 99551 ON CONFLICT (game_id, language_code) DO NOTHING;
