INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The SpongeBob SquarePants Movie', 'On a heroic, comedic quest through 18 levels of platform, driving and sliding action, SpongeBob and Patrick leave Bikini Bottom and journey to new and unexplored lands. Players join their struggle to defeat Plankton''s diabolic scheme to take over the world...Plan Z! Plankton has stolen King Neptune''s crown and assumed control of the town of Bikini Bottom, placing the blame squarely on Mr. Krabs. Together, SpongeBob and Patrick must journey to far away Shell City to recover the crown, return to Bikini Bottom and save the town and Mr. Krabs.' FROM games WHERE igdb_id = 2767 ON CONFLICT (game_id, language_code) DO NOTHING;
