INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Two of a Kind', 'Two of a Kind is a point-and-click adventure game starring a brother/sister detective duo on their first big case. A priceless artifact has been stolen from the local museum, and they are charged with finding out who did it and why.' FROM games WHERE igdb_id = 73625 ON CONFLICT (game_id, language_code) DO NOTHING;
