INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Fútbol 2005', 'PC Fútbol is a soccer managerial game that let you pick your favourite team and take it to the top, if you''re good enough!  You can sign up your favourite players, train the team, expand your stadium, choose sponsors, set the ticket price, etc.  The matches can be seen in 3D so you can give orders to your players in real time, or you can choose to see the final score only.  The game has a big database with 2,000 teams and 48,000 players, and has the Spanish LFP and FIFPro official licenses so all the players have their real names/appearance.' FROM games WHERE igdb_id = 100057 ON CONFLICT (game_id, language_code) DO NOTHING;
