INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scaler', 'Scaler follows the story of a lizard-loving 12-year-old boy named Bobby "Scaler" Jenkins who accidentately stumbles across an evil plot to dominate the world through use of mutated lizards. Scaler is remembered as a niche game that brought interesting ideas and a striking visual style, being a hidden gem for fans of 3D platformers of that era.' FROM games WHERE igdb_id = 4095 ON CONFLICT (game_id, language_code) DO NOTHING;
