INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario: Fushigi no Koro-koro Party', 'Super Mario: Fushigi no Koro-koro Party is an arcade remake of Mario Party 5 that was released exclusively in Japan. It is the first Mario Party arcade game to be developed by Capcom. The difference between this game and the console-based Mario Party game is that the game supports up to six players, instead of only four.' FROM games WHERE igdb_id = 132033 ON CONFLICT (game_id, language_code) DO NOTHING;
