INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('slide-a-lama', 186456, '2004-06-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4boi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf4wd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slide-A-Lama', 'Slide-A-Lama is a two player 2D strategy/puzzle game. The goal is to collect most points by matching at least three tiles of the same type in a five-by-five grid. Players take turns to insert their current tile in one of the rows or columns. If a column is full, the bottom most tiles is crushed, if a row is full, tile falls at the opposite end out of the grid. Once three or more tiles of a kind form a line, the player is awarded points depending on type and number of tiles. With each 60 points of difference between the two players, one of the ten lamas switches the side. The game ends once the first player has all the lamas on their side. The game became popular as a flash game ICQ users could play against their contacts. It later appeared on several mobile platforms and as a website.' FROM games WHERE igdb_id = 186456 ON CONFLICT (game_id, language_code) DO NOTHING;
