INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Skateboarding', 'Backyard Skateboarding is a fast-paced extreme sports game that lets kids skate as a junior version of eight-time world skateboarding champion, Andy Macdonald. The 2006 (GOTY) edition of Backyard Skateboarding features new challenges, missions, gear, power ups, and unlockables. The game also has easier controls and faster gameplay.' FROM games WHERE igdb_id = 49312 ON CONFLICT (game_id, language_code) DO NOTHING;
