INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultra Bust-A-Move', 'Puzzle Bobble (Japanese: パズルボブル Hepburn: Pazuru Boburu?), also known as Bust-a-Move in North America, is a 1994 tile-matching arcade puzzle video game for one or two players created by Taito Corporation. It is based on Taito''s popular 1986 arcade game Bubble Bobble, featuring characters and themes from that game. Its characteristically cute Japanese animation and music, along with its play mechanics and level designs, made it successful as an arcade title and spawned several sequels and ports to home gaming systems.' FROM games WHERE igdb_id = 47317 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 47317 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
