INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('peter-pan-the-motion-picture-event', 49317, '2004-01-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d0t.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peter Pan: The Motion Picture Event', 'Explore, soar and save the day in an action-packed epic adventure, based on Universal Studios'' motion picture event, Peter Pan. Play as Peter Pan and join Wendy, John, Michael and Tinker Bell on a fantastic journey from London to Neverland. Relive fierce pirate battles, hair-raising danger, narrow escapes and ultimately face off against the notorious Captain Hook. Played from a three-quarter view perspective, Peter Pan can fly, jump, dive, roll, walk, and use his sword to fight enemies. In addition to combat, puzzle solving, and platform jumping, players have to collect special objects for extra lives and bonus points. Developed by Saffire, Peter Pan also features digitized scenes from the movie.' FROM games WHERE igdb_id = 49317 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 49317 AND p.igdb_id = 24 ON CONFLICT DO NOTHING;
