INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid Prime 2: Echoes', 'An exploration-driven 3D metroidvania/first-person shooter hybrid and sequel to Metroid Prime (2002) in which Samus lands on Aether, an intricate planet torn into light and dark versions of itself, to help its remaining inhabitants defend against the invaders from its dark incarnation by traversing both the light and dark worlds, acquiring new power-ups and braving oppressive environments.' FROM games WHERE igdb_id = 1108 ON CONFLICT (game_id, language_code) DO NOTHING;
