INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Will Tell: Tezuka Osamu''s Dororo', 'Blood Will Tell is based on the Japanese manga series Dororo, which was created by Osamu Tezuka. It concerns a hero named Hyakkimaru, who has had much of his body stolen by forty-eight fiends, and has prosthetic replacements. Along with his ally, the thief Dororo, Hyakkimaru must defeat all forty-eight fiends.' FROM games WHERE igdb_id = 18864 ON CONFLICT (game_id, language_code) DO NOTHING;
