INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('7-days-a-skeptic', 73478, '2004-07-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ptt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vbiainpmmxyeynwqsrrb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Days a Skeptic', 'Mankind has moved on from mother Earth, and after the invention of warp technology, is fast mapping the universe one light year at a time. Due to a shortage of materials, the Earth Federation instigates a new program to upgrade old and retired vessels. The Mephistopheles, a small ageing scouting craft, is the first ship to undergo the process. Crewed by a new compliment of 6 crewmen, she is assigned to map out the Caracus galaxy. Just a few days into the assignment, the crew of the Mephistopheles discover an unknown artefact floating unprotected in deep space: an ancient metal locker. Ignoring advice from the Federation to leave it for a research vessel, the captain brings it aboard and prepares to lift the lid..' FROM games WHERE igdb_id = 73478 ON CONFLICT (game_id, language_code) DO NOTHING;
