INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('taiko-drum-master--1', 37148, '2004-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ejn.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taiko Drum Master', 'Taiko Drum Master is an entry in Namco''s Taiko No Tatsujin rhythm game series and the first to have a Western release. As in other rhythm games, the goal is to interact with a special controller according to scrolling onscreen prompts timed to music. This game comes bundled with the TaTaCon drum controller, a miniature version of a Japanese taiko drum with sensors in the middle and on the sides. In-game actions are indicated by scrolling circle icons. Red circles indicate hitting the center of the drum, while blue circles require the player to hit the edge. On big circles, the player can hit both center or edge sensors for bonus points. Finally, yellow lines and balloons require the player to perform drum rolls. The game comes with a varied set of tunes: from covered pop hits like Material Girl and ABC to music from other Namco games such as Katamari Damacy and Dragon Spirit and even television theme songs. In addition, there are also several mini-games included on the disc that use the TaTaCon for more esoteric purposes, such as watermelon eating and wolf-stacking.' FROM games WHERE igdb_id = 37148 ON CONFLICT (game_id, language_code) DO NOTHING;
