INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madden NFL 2005: Collector''s Edition', 'Released exclusively for the PlayStation 2, Madden NFL 2005: Collector''s Edition contains all the features of the regular version, plus a wealth of bonus content. This content includes playable classic versions of Madden from the 16-bit era and two versions from the PlayStation One era; a Madden trivia challenge with more than 1000 questions; Madden Moments, where players can relive the greatest moments of the past 15 seasons; and historical playoff teams from the past 15 years with their authentic uniforms. Also exclusive to the Madden NFL 2005: Collector''s Edition will be bonus video content including footage of The Madden Phenomenon, The Music of Madden, an inside look into how this legendary franchise is made each year from scratch, and more.' FROM games WHERE igdb_id = 43381 ON CONFLICT (game_id, language_code) DO NOTHING;
