INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doko Demo Issho: Toro to Ippai', 'Word-based communication game in which you teach new words to Toro, who then passes the information on to a set of black cats known as Kuro. It was released in September 2, 2004 on the PlayStation 2, and would mark the debut of Kuro. The game is compatible with the PS2''s EyeToy accessory.' FROM games WHERE igdb_id = 246061 ON CONFLICT (game_id, language_code) DO NOTHING;
