INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('psi-ops-the-mindgate-conspiracy', 5992, '2004-06-14', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2msx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7luo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psi-Ops: The Mindgate Conspiracy', 'Psi-Ops is an action game with a twist: no longer do you have to rely solely on big weapons and explosions to progress through it - you also have the aid of psychic powers to take down army after army of enemy soldiers. In the game you take the role of Nick Scryer, a secret agent who had his face reconstructed and mind wiped clean in order to infiltrate a growing psychic organization calling itself The Movement. Nick, however, is captured, but manages to free himself and continue his mission to stop The Movement, regaining his psychic abilities along the way. The game mixes regular weapons with the weapons of the mind. You''ll have access to a series of mind powers, such as Telekinesis (the ability to fling object and soldiers around), Pyrokineses (the ability to set things on fire), Mind Drain (for draining Psi power out of foes'' minds) and Remote Viewing (leaving your body behind and exploring the level).' FROM games WHERE igdb_id = 5992 ON CONFLICT (game_id, language_code) DO NOTHING;
