INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burnout-3-takedown', 5761, '2004-09-03', 93, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y53.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc87am.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burnout 3: Takedown', 'Take anarchic driving destruction on a world tour and experience the pure arcade adrenaline-rush of Burnout 3: Takedown. Combine aggressive high-speed racing with the ultimate in slamming crash action to boost your way to the top. Takedown the competition across the USA, Europe and the Far East in over 60 Race events, or crush all comers with Burnout 3: Takedown''s junction-jamming Crash event pileups. Push it to the next level with five competitive multiplayer models, then move the mayhem online to compete against up to seven players. Reap the rewards of dangerous driving, earning Crash $ and Burnout Points to unlock over 60 hot vehicles, coveted skill trophies, front-page headlines and much more. (Source PS2 Game Manual)' FROM games WHERE igdb_id = 5761 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 5761 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
