INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon: Another Wonderful Life', 'Another Wonderful Life''s gameplay is very similar to its predecessors, involving growing crops while taking care of the variety of animals inhabiting the farm. The game also includes the ability to court three bachelors and marry one of them by the end of the first chapter of the story. The game progresses through 6 chapters in the game, which shows the player character going from young adulthood to old age.' FROM games WHERE igdb_id = 78872 ON CONFLICT (game_id, language_code) DO NOTHING;
