INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half-Life 2', '1998. HALF-LIFE sends a shock through the game industry with its combination of pounding action and continuous, immersive storytelling. NOW. By taking the suspense, challenge and visceral charge of the original, and adding startling new realism and responsiveness, Half-Life 2 opens the door to a world where the player''s presence affects everything around them, from the physical environment to the behaviors even the emotions of both friends and enemies.' FROM games WHERE igdb_id = 233 ON CONFLICT (game_id, language_code) DO NOTHING;
