INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sudeki', 6179, '2004-07-20', 66, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2h0u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aro08.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sudeki', 'Sudeki, a world torn apart into light, shadow and dark. Rent asunder by deceit and betrayal, the land cries out for a peace that only four united heroes can bring. Beyond the protective walls of Illumina Castle lie miles of pastoral, rolling countryside, though once a serene landscape, the Aklorian forces have transformed the countryside into a charred battlefield. Simply passing through the region is unsafe, as travellers must be ever alert for ambushes. Four friends have joined together to aid their queen. Though destined to encounter ancient gods, primordial wonders, and marvellous inventions, foes and betrayal haunt their every step. A keen eye could prove vital, exposing essential clues. And as the companions make their way through darkness and light, they’ll discover that those two extremes have more in common than they once imagined... Real-time, bone-crunching combat with incredible spells and combos.Control any one of the four champions at any time, and skip between them at will.Customise each character''s armour, weapons and spells and evolve new powerful attacks.' FROM games WHERE igdb_id = 6179 ON CONFLICT (game_id, language_code) DO NOTHING;
