INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ballance', 20895, '2004-04-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9trv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar27dx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ballance', 'In Ballance, you control a sphere with the simple objective of navigating it to the end of each of the game''s 12 linear levels. Expect surreal environments as you transform between three different materials to push boxes, spheres, and other objects to clear a path towards the end. Pre-placed "Transformers" will turn your ball into either Paper, Wood, or Stone, each with their own downsides and advantages. Paper can, for example, use gusts of wind to reach higher elevations, fall slower than the other materials, and get around quickly. Stone may be required to push heavy materials, but, due to its immense weight, will experience different issues when trying to navigate environments. Wood is the neutral material of choice: it rolls reliably and quickly, allowing it to stick to sideways railing while still being able to push objects of a medium density.' FROM games WHERE igdb_id = 20895 ON CONFLICT (game_id, language_code) DO NOTHING;
