INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire: The Masquerade - Bloodlines', 'A first- and third-person Western RPG based on the Vampire: The Masquerade tabletop RPG with a heavy emphasis on character building and role-playing, in which the player embodies a fledgling vampire under the guidance of vampire prince Sebastian LaCroix. The player must serve the prince while getting to know the various factions of vampires in Los Angeles and forming their own political views.' FROM games WHERE igdb_id = 11 ON CONFLICT (game_id, language_code) DO NOTHING;
