INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smugglers 3', 'Play a greedy trader, an ambitious bounty hunter or a ruthless pirate and attack whole planets in this sci-fi trading game. Backed up by a crew of different kinds of crewmen (like droids or mercenaries) you can visit more than 75 planets in 25 systems in your attempt to gain favors with one of the four factions in the known galaxy.' FROM games WHERE igdb_id = 140099 ON CONFLICT (game_id, language_code) DO NOTHING;
