INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sacred', 'A shadow of evil has fallen on the kingdom of Ancaria. Now is the time for champions. Orcish hordes and Undead legions, Demonic beasts and mythical Dragons. This is the world of Sacred. A time of legends. Your world. Your time. A new adventure begins...' FROM games WHERE igdb_id = 328 ON CONFLICT (game_id, language_code) DO NOTHING;
