INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alida', 7665, '2004-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jby.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6dfs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alida', 'Your adventure begins when you’re secretly dropped off on the island of Alida. The story centers around four young men in the band Alida who attained phenomenal success with their first CD release. Loads of money coupled with wild imagination resulted in the band’s construction of a guitar-shaped island theme park. Alida was abandoned when money woes and paranoia set in and the band split up. Now, several years later, the band’s manager suggests a reunion on the island. Soon thereafter band member Arin leaves for the island and is not heard from again. His wife Julia sends you to Alida to find Arin and bring him home.' FROM games WHERE igdb_id = 7665 ON CONFLICT (game_id, language_code) DO NOTHING;
