INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Counter-Strike: Condition Zero Deleted Scenes', 'Being a standalone game, Deleted Scenes is a collection of 12 single player missions that came as a bonus with Counter-Strike: Condition Zero. The missions are not connected with each other, but every of them share the same theme: terrorism and warfare.' FROM games WHERE igdb_id = 93807 ON CONFLICT (game_id, language_code) DO NOTHING;
