INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sid Meier''s Pirates!', 'Based on Sid Meier''s original masterpiece, Pirates!, Sid Meier''s Pirates! has you facing countless dogged enemies, wooing fair maidens and raising the Jolly Roger on the high seas in pursuit of riches. Discover what it takes to become one of the most famous pirates in history! Firaxis'' long-awaited Sid Meier''s Pirates! carries on with the great game play tradition and design simplicity of the award-winning original while adding more challenging and exciting battle options, eye-popping 3D graphics, fantastic new audio, and loads of new game play features!' FROM games WHERE igdb_id = 868 ON CONFLICT (game_id, language_code) DO NOTHING;
