INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GoldenEye: Rogue Agent', 'GoldenEye: Rogue Agent is a first-person shooter video game developed by EA LA and published by Electronic Arts. The player takes the role of an ex-MI6 agent Jack Hunter, who is recruited by Auric Goldfinger (a member of a powerful unnamed criminal organisation based on Ian Fleming''s SPECTRE) to assassinate his rival Dr. No. Several other characters from the Bond series make appearances throughout the game, including Pussy Galore, Oddjob, Xenia Onatopp and Francisco Scaramanga. Despite its name and being part of the James Bond universe, the game has no relation to the 1995 film or the 1997 video game of the same name. In this setting the game''s protagonist is given the name ''GoldenEye'' after he loses his eye and receives a gold-colored cybernetic replacement.' FROM games WHERE igdb_id = 1632 ON CONFLICT (game_id, language_code) DO NOTHING;
