INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robin Hood: Forest Adventures', 'Robin Hood: Forest Adventures is a budget platformer. Designed for kids, controls are limited to the 3 keyboard arrows (down arrow is not used). The game features four levels to explore. Just collect bonuses, get fruits, and jump over enemies to "kill" them since there is no violence. An arch is your only weapon.' FROM games WHERE igdb_id = 394460 ON CONFLICT (game_id, language_code) DO NOTHING;
