INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Men of Valor', 'Vietnam, 1965. You are Dean Shepard, a "cherry" to the ''Nam with zero war experience other than standard boot camp training at Parris Island, SC. Along with your platoon, you will fight the NVA and the Vietcong in true historic locales and battles.' FROM games WHERE igdb_id = 5913 ON CONFLICT (game_id, language_code) DO NOTHING;
