INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Arthur', 'Experience the excitement and feel of the Jerry Bruckheimer film, King Arthur as you play through Arthur''s world amidst photo-realistic scenery. Players can chose to play as Arthur, Lancelot, Tristan, Bors and Guinevere; each with their own attack moves and combos, and challenge friends through the multi-player combat option. Other game features include well executed horseback combat levels and seamless cutscene to gameplay transitions.' FROM games WHERE igdb_id = 3967 ON CONFLICT (game_id, language_code) DO NOTHING;
