INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Konga 2: Hit Song Parade!', 'A rhythm and beat game like the popular Dance Dance Revolution game series, but instead of matching the beats with your feet you use your hands to play the bongos. Starring the characters from the Donkey Kong series of games. There are more than 30 tunes to drum beats to, from every genre of music - pop favorites to classical remixes. The more on-time your beats are with the music the higher score you get to earn more coins to unlock different beat sounds.' FROM games WHERE igdb_id = 3890 ON CONFLICT (game_id, language_code) DO NOTHING;
