INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neolithic: To the End', 'A modern-day open-world RPG about a secret world. With the help of your companions, some demons, some cats, and any supernatural entities you can bend to your will, all the different ways to solve problems, you may still fail to save the world. Life is simply unfair. But, will you stop trying?' FROM games WHERE igdb_id = 159762 ON CONFLICT (game_id, language_code) DO NOTHING;
