INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom 3', 'A massive demonic invasion has overwhelmed the Union Aerospace Corporation''s (UAC) Mars Research Facility, leaving only chaos and horror in its wake. As one of only a few survivors, you must fight your way to hell and back against a horde of evil monsters. The path is dark and dangerous, but you''ll have an array of weapons--including a pistol, a chainsaw, grenades, and more--to use for protection.' FROM games WHERE igdb_id = 280 ON CONFLICT (game_id, language_code) DO NOTHING;
