INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Prisoner of Azkaban', 'Harry Potter and the Prisoner of Azkaban is the sequel to Harry Potter and the Chamber of Secrets for PC and Mac, and features similar action-adventure and platforming gameplay. The player controls both Harry as well as his friends Ron and Hermione, while casting spells, solving puzzles and fighting enemies. When not engaged in a specific mission, the castle of Hogwarts can be freely explored. Scattered all around Hogwarts, usually in hidden areas, are Every Flavour Beans, Pumpkin Pasties and Cauldron Cakes, which function as a sort of currency. They can be traded for Collectors Cards, passwords for portraits that lead to more secret areas, and power-ups.' FROM games WHERE igdb_id = 3943 ON CONFLICT (game_id, language_code) DO NOTHING;
