INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-legend-of-heroes-trails-in-the-sky', 8986, '2004-06-24', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7ybm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4t0p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes: Trails in the Sky', 'The Legend of Heroes: Trails in the Sky is the first installment in the main Trails series, serving as the beginning to the Liberl arc and the series as a whole. The game follows protagonists Estelle Bright and her adopted brother Joshua, who journey through the country of Liberl to train to become senior Bracers, members of a non-government multinational organization that acts to keep the peace and protect civilians. Nihon Falcom comes a series of RPGs telling a legend of adventure, political intrigue, and mystery, with a tale of growing up at the core. With a mix of turn-based and strategy combat, battles will cause unique builds and plans to handle many different situations and allow for different play styles. Wonderfully detailed characters abound, even to the smallest NPC, and the player will find themself taking the world in at every turn. Trails in the Sky sets a new standard for making an enjoyable and immersive RPG.' FROM games WHERE igdb_id = 8986 ON CONFLICT (game_id, language_code) DO NOTHING;
