INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kult-heretic-kingdoms', 9675, '2004-10-01', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21b6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/iyxc16onr6wmplv5apm8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kult: Heretic Kingdoms', 'In the world of the Heretic Kingdoms, a world where God is dead and religion heresy, you are cast as a young female inquisitor, working to stamp out the last remnants of religion. On instructions to destroy a relic which the Inquisition considers to be a significant threat, you are drawn into a war between two warring secret societies – a conspiracy of mages whose goal is true power, and a shadowy cult who seeks to resurrect the Dead God. As the story progresses, you will be placed in an amoral world and left to decide your own morality. Just like the real world, your actions have consequences, and it is up to you to decide if you can live with them or not. Play as an altruistic heroine, a vicious and selfish egotist, or just a woman trying to get her job done – your actions will lead you to one of six different endings depending on where you decide your loyalties lie. Will you crush religion underfoot, or become its savior? Only you can decide.' FROM games WHERE igdb_id = 9675 ON CONFLICT (game_id, language_code) DO NOTHING;
