INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Second Sight', 'Second Sight is primarily stealth-action, using psychic abilities to stealthily move through levels. Due to it''s dark atmosphere, it could be considered a psychological thriller. The game focuses on John Vattic''s exploration of his own mind, discovering psychic abilities and a dark history before his amnesia.' FROM games WHERE igdb_id = 4101 ON CONFLICT (game_id, language_code) DO NOTHING;
