INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA Soccer 2005', 'FIFA Football 2005 gives you more control than ever with improved button and control sensitivity and an intuitive Off the Ball Control. Now you can take command of players not in possession of the ball by calling in tackles, jostling for space, and sending your teammates on runs as you control the pitch. With more than 350 official team and league licenses from around the world, an enhanced Career mode, and an improved broadcast, FIFA Football 2005 gives you a complete and authentic soccer experience.' FROM games WHERE igdb_id = 703 ON CONFLICT (game_id, language_code) DO NOTHING;
