INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Magic Flute', 'In his dream, Wolfie travels to the magical kingdom of the Queen of the Night, who has stolen the sun from the world. Wolfie and our young players must save the world with their musical prowess and find the missing Princess Pamina and Prince Tamino.' FROM games WHERE igdb_id = 60386 ON CONFLICT (game_id, language_code) DO NOTHING;
