INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-ball-z-budokai-3', 2566, '2004-11-16', 88, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dfo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7dv1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Budokai 3', 'The third installment in the Dragon Ball Z: Budokai series begins another tournament of champions where only one fighter can prevail. As one of the characters from the Dragon Ball Z animated series, you can master an all-new fighting system that lets you teleport, juggle opponents, fly, and attack in a variety of ways. As you progress through the tournament, you can unlock up to 40 bonus characters from the DBZ universe. You can also post and retrieve character profiles from the Internet.' FROM games WHERE igdb_id = 2566 ON CONFLICT (game_id, language_code) DO NOTHING;
