INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock Holmes: The Silver Earring', 'The party Sherlock Holmes and his trusted friend, Dr. Watson, have been invited to turns into tragedy: a murder is committed right before their very eyes. Our famous detective is on the case immediately, but the list of suspects is getting no shorter, while other crimes are being committed. Will you succeed in uncovering the truth before other innocent people suffer? Experience an amazing plot, written by a true Sherlock Holmes fan, in a unique environment.' FROM games WHERE igdb_id = 6812 ON CONFLICT (game_id, language_code) DO NOTHING;
