INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planetarian: The Reverie of a Little Planet', 'Planetarian: The Reverie of a Little Planet is a Japanese post-apocalyptic visual novel developed by Key and is rated for all ages. The story centers on a middle-aged man who comes across a malfunctioning robot in a dead city. The man, known simply as "the junker", stays with this robot for a time and attempts to fix the projector of the planetarium where the story takes place.' FROM games WHERE igdb_id = 11413 ON CONFLICT (game_id, language_code) DO NOTHING;
