INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mystery of the Art School', 'The Art School, a legendary institute deep inside the city of Toledo, a peaceful place until a promising pupil gets desappeared. Play as Willtif Smothson, a student of the Art School who gets involved into an adventure that will never forget. Walk through the classes of the Art School, meet the students, and the teachers that makes this place unique. The Mystery of the Art School is based on the real Art School…' FROM games WHERE igdb_id = 321162 ON CONFLICT (game_id, language_code) DO NOTHING;
