INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GoPets', 'GoPets was a virtual pet site that involved raising a customized three-dimensional pet downloaded onto a user''s computer. GoPets was launched on August 4, 2005 and closed on November 8, 2009. GoPets resided not only on their owners'' computers, but also visited GoPets members around the world when sent, invited or when pets decide to travel on their own.' FROM games WHERE igdb_id = 203176 ON CONFLICT (game_id, language_code) DO NOTHING;
