INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('worlds-best-chess-fritz-8-deluxe', 93043, '2004-11-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa43z.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World''s Best Chess: Fritz 8 Deluxe', 'World''s Best Chess: Fritz 8 Deluxe is an enhanced edition of Fritz 8, an interactive game for chess players of all levels, from beginners to experts. Like the previous version, this Deluxe release offers the player choices of either 2D or 3D interactive boards. This adds 6 new 3D boards including one called the "Spanish Room". The searchable database has been enlarged and the engine has been improved. In addition, world champion chess player Garry Kasparov provides his knowledge and expertise in a training video during gameplay. A one-year membership in playchess.com opens up internet play.' FROM games WHERE igdb_id = 93043 ON CONFLICT (game_id, language_code) DO NOTHING;
