INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperDanny''s Adventure', 'A wacky little adventure whipped up in a matter of days as a Christmas present for SuperDanny himself, SuperDanny''s Adventure features numerous gameplay styles across eight levels filled with loads of inside jokes, mixed sprites, mixed musics and all manner of ridiculousness. And a cheesy engine to boot.' FROM games WHERE igdb_id = 210344 ON CONFLICT (game_id, language_code) DO NOTHING;
