INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Maze', 'Help sweet Lily to escape the Land of Nod and return home in Crystal Maze! Gather crystals on each dimensional level while avoiding danger. Collect enough crystals and Lily will escape. But BEWARE. Lily must move fast to avoid being captured by the Dream Reaper and the lifeless mummies. You''ll love the beautiful graphics, soundtrack, and all the surprises that Crystal Maze offers!' FROM games WHERE igdb_id = 85792 ON CONFLICT (game_id, language_code) DO NOTHING;
