INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaiketsu Zorori: Mezase! Itazura King', 'Kaiketsu Zorori: Mezase! Itazura King is a Miscellaneous game based on the popular Japanese children''s book character Kaiketsu Zorori, developed and published by Bandai. Released exclusively in Japan in 2004. Using the EyeToy camera, you can put yourself in the game and appear alongside Zorori, Ishishi and friends. There are nine different types of mischief you can cause -- the ultimate objective is to outdo Zorori himself. There is also a party mode where up to four players compete consecutively to become the King of Pranks.' FROM games WHERE igdb_id = 307269 ON CONFLICT (game_id, language_code) DO NOTHING;
