INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aqua Kids', 'Aqua Kids is an action game based on the Japanese animated CG TV show broadcast on TV Tokyo. Two modes of play are available. A battle mode has you collect items and defeat enemies. A "Help Daibo" mode has you find items in order to power up your "Daibo" robot.' FROM games WHERE igdb_id = 269345 ON CONFLICT (game_id, language_code) DO NOTHING;
