INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SSX Snowboarder', 'Get off the couch and onto the slopes with this cool Play TV SSX Snowboarder set. Just plug the unit into your TV or VCR and hop on the board for some real snowboarding action. Your moves on the snowboard control the action as you cruise SSX courses and perform heart-stopping tricks as you become one of your favorite SSX characters. You can almost feel the powder as you watch and hear the realistic graphics and sounds on the screen.' FROM games WHERE igdb_id = 251301 ON CONFLICT (game_id, language_code) DO NOTHING;
