INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MaxPlay Classic Games Volume 1', 'A compilation of video games for the Nintendo GameCube and PlayStation 2. The collection features ten games, all unofficial remakes of classic games. It includes: Invaders, Loop the Loop, Dragon Tiles 3, Bounty Hunter X, Chopper 2, Jetpack 2, Paddle Panic, Pop ''Em, Promixa, and Super Power Shot. Available only in Europe. It is the only unlicensed game for the GameCube and one of only a handful for the PlayStation 2.' FROM games WHERE igdb_id = 3996 ON CONFLICT (game_id, language_code) DO NOTHING;
