INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zero One SP', 'Nagoya always suffers from mysterious dreams. One day he is invited by his classmates on a drinking party to celebrate the last day of semester. They hear piano playing at night school. Depending on actions, the mystery can have four absolutely different and often fantastic reasons.' FROM games WHERE igdb_id = 93952 ON CONFLICT (game_id, language_code) DO NOTHING;
