INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ore-no-ryomi-2', 240535, '2004-04-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6896.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scllh1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ore no Ryomi 2', 'Ore no Ryomi 2: The Restaurant is a restaurant management game. Similarly to its predecessor, it''s an action-strategy game where the player must manage his funds and personally prepare all the dishes for the customers. Before the start of each day, the player can spend money to purchase expansions for his restaurant, including new food menu items and proper equipment. Once the day starts, the player must manage his time carefully to cater to all the customers and the restaurant''s needs from morning till closing hours. Throughout the day, new customers keep coming in and ordering food, and events (such as the need to wash dishes or a fire in the kitchen) require the manager''s attention. Each customer and event is represented by a gradually vanishing bar. Preparing food and caring for problems is usually done through a simple, action minigame. The player can only take on one of these at a time, but it is possible to serve prepared meals to customers in the middle of something else. Each customer expects his food to be prepared strictly according to order. If the player messes something up by adding the wrong ingredients or by under- or overcooking the food, the customer will pay less. And if a customer waits too long without their order being attended to, they get furious and leave, causing a minor monetary penalty. Things get even more hectic during the "Rush Hour" that comes twice daily, during which large crowds of customers keep coming in. Ore no Ryomi 2 also contains several "Challenges": the player, invited to the Iron Chef TV show, tries to complete a specific difficult task, such as preparing many perfect dishes in a limited time. Throughout the game, the player receives trophies and awards, which he can proudly view in his Trophy Room if he has purchased them.' FROM games WHERE igdb_id = 240535 ON CONFLICT (game_id, language_code) DO NOTHING;
