INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silver Strike Bowling', 'Silver Strike Bowling is an arcade game that mimics ten-pin bowling on a monitor corresponding to a player''s trackball control. Users may play standard bowling games or, depending on local availability, can select the Vegas Tournament option allowing players to draw cards for each spare and strike in an attempt to produce the best poker hand. While relatively basic, the 8 players mode and leaderboards can keep players coming back for more.' FROM games WHERE igdb_id = 72780 ON CONFLICT (game_id, language_code) DO NOTHING;
