INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big''s Fishing', 'Big''s Fishing is an LCD game created for distribution in McDonald''s chain of fast food restaurants. They were offered as a part of Happy Meals for a limited time in 2004. The main goal of the game is to move Big''s fishing hook up and down appropriately to catch the fish that appear on the screen. If the player misses 3 fish, the game will end. The game has a directional pad with only the up and down arrows and also a single button.' FROM games WHERE igdb_id = 198597 ON CONFLICT (game_id, language_code) DO NOTHING;
