INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super DX-Ball', 'Super DX-Ball delivers a vibrant and colorful brick-breaking game that the whole family can enjoy. Created by Michael P. Welch, the original author of DX-Ball, this game brings together the amazing world of tessellation and repeating patterns with the classic game play of DX-Ball. Hand-crafted by an old pro, Super DX-Ball is the quintessential brick-breaking game that you''ve been searching for.' FROM games WHERE igdb_id = 73985 ON CONFLICT (game_id, language_code) DO NOTHING;
