INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breakdown', 'Trapped inside a mysterious laboratory and unable to remember his past, Derrick Cole discovers his extraordinary powers, as he fights for survival against a determined military faction and a legion of seemingly invincible super-human warriors! Breakdown offers an exciting first-person action-adventure gaming experience by combining hand-to-hand combat and state-of-the-art weapons with an intense story line and incredible graphics. Embark on a thrilling and suspenseful search for the truth!' FROM games WHERE igdb_id = 5756 ON CONFLICT (game_id, language_code) DO NOTHING;
