INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Varmintz', 'Released way back in 2004 and developed by Skunk Games, this Frogger clone expands upon the formula and makes it stand out from the inspiration by throwing in absurd, cartoon art style reminiscent of early 2000''s Cartoon Network shows, a catchy music, bonus levels and power ups. And raccoons. Five raccoons. All with their own personalities and voices.' FROM games WHERE igdb_id = 9063 ON CONFLICT (game_id, language_code) DO NOTHING;
