INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dancing Stage Unleashed', 'Dancing Stage Unleashed, or DS Unleashed, was released by Konami Digital Entertainment GmbH to the European Xbox audience on March 12, 2004. A sister release to the North American Dance Dance Revolution Ultramix, it features the same look and feel and the same options as Ultramix, including online play and content download through Xbox Live. Unleashed has a unique soundtrack and features music from Big Brovaz, Blondie and The Wonder Stuff as well as original tracks from Konami''s in-house artists. The original release was followed by two sequels, Dancing Stage Unleashed 2 and 3, released May 13, 2005 and March 17, 2006 for the Xbox in Europe.' FROM games WHERE igdb_id = 5803 ON CONFLICT (game_id, language_code) DO NOTHING;
