INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Longing Ribbon', 'You and two friends find yourselves lost in the woods one day and decide to seek refuge in a nearby mansion. Certainly nothing could go wrong; people do that sort of thing all the time, don''t they? But what you are about to discover is that this is no ordinary mansion, and its inhabitants are no ordinary people...' FROM games WHERE igdb_id = 151694 ON CONFLICT (game_id, language_code) DO NOTHING;
