INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('midnight-nowhere', 12446, '2004-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wfx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ustmwfrqqr1hs5swu1nd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Nowhere', 'In Midnight Nowhere, you play a man suffering from amnesia who wakes up in the morgue. Half-naked, dead bodies and blood are everywhere. Something is very wrong, but he hasn''t a clue what happened, where he is or even who he is. The city of Black Lake, Russia, is in a state of panic because no one has any idea who or what is behind the horrific slaughters - now numbering in the hundreds. Is it a serial killer? ... or is it something even more evil? You play this point-and-click, mouse-driven game in 3rd-person perspective. Features include animated characters, a mix of 2D and 3D graphical backgrounds and a mood-enhancing soundtrack. To advance the story, find and use inventory objects, read different types of documents, solve various types of puzzles, and talk to numerous characters. Falling solidly under the Horror category, the subject matter is not for the faint of heart. The strong language and adult sexual themes are in keeping with today''s "R-rated" films.' FROM games WHERE igdb_id = 12446 ON CONFLICT (game_id, language_code) DO NOTHING;
