INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 45: The Koi to Namida to, Tsukioku to... - Thread Colors Sayonara no Mukougawa', 'The game takes place primarily at the hospital and the local high school where the girls drift in and out of the player''s daily life. During the hospital stay, our hero befriends a girl who tends to be sickly and naïve to the ways of the world but perhaps the two will help each other recover from their respective ailments.' FROM games WHERE igdb_id = 203265 ON CONFLICT (game_id, language_code) DO NOTHING;
