INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totally Spies!: Swamp Monster Blues', 'Totally Spies!: Swamp Monster Blues" is an educational puzzle game based on the "Totally Spies!" animated series. In this adventure, players control the trio of teenage spies—Sam, Clover, and Alex—as they investigate reports of monsters in the Louisiana Bayou to rescue a kidnapped government agent.' FROM games WHERE igdb_id = 206090 ON CONFLICT (game_id, language_code) DO NOTHING;
