INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sly-2-band-of-thieves', 1799, '2004-09-14', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobcx5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6szp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sly 2: Band of Thieves', 'Sly 2: Band of Thieves is a stealth-action platformer developed by Sucker Punch Productions and released for PlayStation 2 in 2004. Players control Sly Cooper and his gang as they attempt to dismantle the Klaww Gang and recover the scattered parts of Clockwerk. The game expands on its predecessor with open-ended mission structures, multiple playable characters, and improved stealth mechanics. The story takes place two years after Sly Cooper and the Thievius Raccoonus. In the first game, Sly was becoming a professional thief, but in Band of Thieves, he is a professional thief, so he retains all of the moves from the first game. He also earns new moves and gains different items to assist him in his dark craft. Players might start a level as Sly, and then after completing a particular task, players switch to Bentley, and Murray, respectively.' FROM games WHERE igdb_id = 1799 ON CONFLICT (game_id, language_code) DO NOTHING;
