INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Sea 2', 'Two years after the events of the first title, the star system Theophilus is under attack by a force called "Menace". Sent to defend the galaxy once more, Sho meets a new Vipa named Feanay, who is seemingly tied to the Menace. Together, they fight to destroy Menace and discover Feanay''s true origin.' FROM games WHERE igdb_id = 22166 ON CONFLICT (game_id, language_code) DO NOTHING;
