INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World War 2: Pacific Heroes', 'World War 2: Pacific Heroes is an aerial combat simulator game set in the Pacific Theater of Operations during World War II. In the game, you take off from massive aircraft carriers to shoot down enemy fighters and torpedo Japanese war ships, then switch views to man anti-aircraft artillery guns defending against enemy raids. The planes and cannons you control are realistic and the enemies are relentless! WW2 Pacific Heroes is a high-end, console-like game featuring 20 pulse-pounding missions and spectacular 3D scenery. Do you have what it takes to clear the skies?' FROM games WHERE igdb_id = 24746 ON CONFLICT (game_id, language_code) DO NOTHING;
