INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crescent Suzuki Racing', 'Only Crescent Suzuki Racing: Superbikes and Super Sidecars puts you in control of dozens of the meanest superbikes and sidecars on the international circuit, including the GSX-R1000 of British Superbike rider John Reynolds and the fearsome Super sidecar of 2003 world champion Steve Webster. Chicanes, gravel traps and other hazards await you across many amazing race tracks and the ruthless skill of your computer opponents is sure to test your racing technique to the limit. An exciting two-player mode lets you and a friend go head-to-head on every circuit in the game, and even race superbikes and sidecars against each other in the ultimate grudge match!' FROM games WHERE igdb_id = 10112 ON CONFLICT (game_id, language_code) DO NOTHING;
