INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FireChild: Born Into the Fire', 'FireChild: Born Into the Fire is a 2D side-scroller game. The player controls the hero through scrolling environments, battling incoming enemies, avoiding traps and all sorts of dangers while picking power ups. Quick reflexes, eagle-eyed precision and the help of the Ancestors will be needed to succeed in this most dire quest, to reach the ominous Black Isle to rescue her brother from the clutches of the Sanam.' FROM games WHERE igdb_id = 123095 ON CONFLICT (game_id, language_code) DO NOTHING;
