INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s Deer Hunt: 2005 Season', 'Cabela''s Deer Hunt: 2005 Season is the first sequel to Cabela''s Deer Hunt: 2004 Season. It was developed by Sand Grain Studios (PlayStation 2), Magic Wand Productions (Windows) and FUN Labs (Xbox) and released on August 31, 2004.  The game was published by Activision, in conjunction with hunting supply company Cabela''s.' FROM games WHERE igdb_id = 5765 ON CONFLICT (game_id, language_code) DO NOTHING;
