INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Tour Soccer 2005', 'Features more than 900 teams from around the world -- over 18,000 players in all Play classic, world-famous teams like 90''s Barcelona team, the 80''s Milan team and the 70''s Liverpool team Revolutionary new icon passing system and intuitive controls make controlling the action easy Advanced AI give players a challenge, every time they play the computer Multiple game modes for each type of soccer fan - jump right in for a quick Exhibition Game, battle it out over a Season, or try Career & Challenge Modes' FROM games WHERE igdb_id = 23546 ON CONFLICT (game_id, language_code) DO NOTHING;
