INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Over 1000 Jigsaw Puzzles', 'Over 1000 Jigsaw Puzzles is a fully featured jigsaw program. Unlike some games in this genre which come with a dozen or so pictures that can be played with multiple numbers of pieces, this game comes with 1,029 pictures that of varying degrees of difficulty. It also allows the player to create their own jigsaws using half a dozen or so different styles of puzzle piece and up to six thousand pieces. Other features include optional piece rotation, sound effects, music, an optional ''ghost'' image of the completed picture, a save/load feature and an option to download additional pictures from the internet.' FROM games WHERE igdb_id = 228409 ON CONFLICT (game_id, language_code) DO NOTHING;
