INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Ages 2500 Vol. 11: Hokuto no Ken', 'Hokuto no Ken is perhaps the most substantial upgrade in the Sega Ages 2500 series, being an remake of the 1986 Sega Mark III release of Hokuto no Ken (known as Black Belt in the west). It is presented entirely in 3D (though gameplay still takes place on a 2D plane). There are more moves and it is more closely linked to the anime.' FROM games WHERE igdb_id = 100099 ON CONFLICT (game_id, language_code) DO NOTHING;
