INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konohana 4: Yami wo Harau Inori', 'Konohana 4: Yami o Harau Inori is the fourth entry of the mystery visual novel series Konohana, in which Meguru Momoi, Miako Tachibana, and Shinobu Sakurada take a bullet train for an excursion trip to Kyoto, only for them to hear a scream and stumble upon a murder scene, now they have to figure who''s the culprit behind this.' FROM games WHERE igdb_id = 213933 ON CONFLICT (game_id, language_code) DO NOTHING;
