INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-chronicles-of-riddick-escape-from-butcher-bay-the-developers-cut', 24169, '2004-12-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21ia.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsu59.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chronicles of Riddick: Escape from Butcher Bay - The Developer''s Cut', 'The most wanted man in the universe comes to your neighborhood in The Chronicles of Riddick: Escape From Butcher Bay. Set before the events of two movies, The Chronicles of Riddick and Pitch Black, the game tells the story of Riddick''s escape from the previously inescapable maximum security prison Butcher Bay, which is home to the most violent prisoners in the galaxy. Battle your enemies in first-person or third-person views using shooting, stealth, or hand-to-hand combat. With Riddick''s eye-shine, you can easily see through the dark to take out your foes.' FROM games WHERE igdb_id = 24169 ON CONFLICT (game_id, language_code) DO NOTHING;
