INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Mobile: Groovy Arche', 'Groovy Arche is a minigame from the PlayStation version of Tales of Phantasia that was re-released as part of the Tales of Mobile series. Groovy Arche sees the player assuming the role of Arche Klein as she flies across a horizontally scrolling screen, blasting enemies with upgrade-able magic spells and dodging up and down to avoid incoming fire.' FROM games WHERE igdb_id = 294600 ON CONFLICT (game_id, language_code) DO NOTHING;
