INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer Life!', 'Starting as an amateur footballer by training hard and making correct career choices you can gradually become a world famous professional. Apart from the football side of your career you will also be able to manage aspects of your personal life, including friendships and rivalry, dating, marriage and even raising children.' FROM games WHERE igdb_id = 44697 ON CONFLICT (game_id, language_code) DO NOTHING;
