INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bobobo-bo Bo-bobo: Atsumare! Taikan Bo-bobo', 'Based on the manga where the main man with a funky afro attacks opponents with his nose hairs. This time you get well and truly involved in the madcap manga mayhem with your off screen persona being mapped for movements in the game mini challenges. Absolutely mad, but we love it.' FROM games WHERE igdb_id = 79699 ON CONFLICT (game_id, language_code) DO NOTHING;
