INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'After the End', 'Your patrol cruiser received mayday signal from a research base on a suburban planet "Rydon 7". The dropship directed to investigate the situation was hit and damaged, and you are the only survivor. Do you dare to go out of the ship and see what''s outside? Cut your way through locations filled with mutants in your attempt of getting replacement units for your dropship and discovering the source of the evil raging all over the planet.' FROM games WHERE igdb_id = 73577 ON CONFLICT (game_id, language_code) DO NOTHING;
