INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strawberry Shortcake: Summertime Adventure', 'Strawberry Shortcake: Summertime Adventure promises a wealth of adventurous fun as Strawberry Shortcake prepares her entries for the Strawberryland Bake-Off. Join Apple Dumplin'', Orange Blossom, Angel Cake and Ginger Snap in two different modes of play - Berry Garden Mode and Strawberryland Adventure Mode, as they attempt to grow the best berry and use it to win the bake-off. With perplexing puzzles, peculiar power-ups and persnickety plant seeds, Strawberry Shortcake: Summertime Adventure offers players a "berry" good time.' FROM games WHERE igdb_id = 8570 ON CONFLICT (game_id, language_code) DO NOTHING;
