INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'McFarlane''s Evil Prophecy', 'In the 19th century, the dead are rising from their graves and other chaos is happening all over the world. People fear that the end of the world is coming. A book predicts that an eternal age of darkness on Earth is beginning. Dr. Hans Jaeger summons three of the best monster hunters in the world to fight the evil creatures: Logan the pirate, Delphine the gunslinger, and Sundano, a mystical African warrior. Among the monsters are Dracula, Frankenstein''s monster, the werewolf, the mummy, the sea creature, and the voodoo queen.' FROM games WHERE igdb_id = 43633 ON CONFLICT (game_id, language_code) DO NOTHING;
