INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Hina Sim Date RPG', 'Practice getting a date with Love Hina characters. Meet girls, talk to them, make them like you. Love Hina Sim Date RPG is based on the popular Japanese animation Love Hina. Begin by choosing the name for the main protagonist and allocate the available 40 points into age, power, intelligence, and magic levels. The main goal is to get one Hina girl to fall for you and become your girlfriend and your Valentine’s date. Try to gain as much money and experience as possible.' FROM games WHERE igdb_id = 185840 ON CONFLICT (game_id, language_code) DO NOTHING;
