INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galactic Wrestling featuring Ultimate Muscle: The Kinnikuman Legacy', 'Galactic Wrestling: Featuring Ultimate Muscle puts you in the fast and exciting wrestling action of the Ultimate Muscle cartoon. You can choose from more than 45 characters--each with unique moves--plus hidden wrestlers that you can unlock. Go toe-to-toe against unusual opponents in modes such as Tag Team and Battle Royal. Slam up to three of your friends in seven different rings. Easy to learn, yet difficult to beat, Galactic Wrestling: Featuring Ultimate Muscle lets you exercise your fighting skills.' FROM games WHERE igdb_id = 43679 ON CONFLICT (game_id, language_code) DO NOTHING;
