INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Colosseum II', 'Dedicated to all of the professional wrestling fans around the world, the birth of the strongest in professional wrestling games is finally here. Over 150 real to life licensed wrestlers, over 2800 motion capped moves! This is wrestling at maximum volume, the strongest work. This is the "King of Colosseum II!' FROM games WHERE igdb_id = 43676 ON CONFLICT (game_id, language_code) DO NOTHING;
