INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MTX Mototrax', 'Experience wicked air and in-you-face action in the most complete motocross game ever offered! Featuring licensed bikes, top pro riders and all the gut-wrenching, high-flying bike action of today''s coolest sport! Learn how to perform over 100 different tricks to earn cold, hard cash from contest wins and sponsorships that you will need to make it to the ultimate motocross competetion - The X Games!' FROM games WHERE igdb_id = 5935 ON CONFLICT (game_id, language_code) DO NOTHING;
