INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man 2: Activity Center', 'Just like Spider-Man, kids can swing from the rooftops of Manhattan fighting crime and battling the evil Doc Ock in an interactive learning environment. Spider-Man Activity Center features seven challenging activities based on specific movie events that all take place in key locations. The game''s activities involve saving Mary Jane, identifying the criminals, creating mixtures in the lab, and more. Actors from the movie Spider-Man 2 lend their voices to the game.' FROM games WHERE igdb_id = 208788 ON CONFLICT (game_id, language_code) DO NOTHING;
