INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'La Statuette maudite de l''oncle Ernest', 'You and Chipikan embark again on an adventurous journey through Asia in order to find a secret formula that is needed to save Chipikans people. Together you will unveil the mysterious discoveries of the great adventurer Uncle Albert by solving many riddles and overcoming obstacles with courage, dexterity and logic thinking. You will do this by navigating through Uncle Alberts Notebook where every new page yields a new surprise.' FROM games WHERE igdb_id = 282689 ON CONFLICT (game_id, language_code) DO NOTHING;
