INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MC Groovz Dance Craze', 'Produced by the long-time peripheral maker Mad Catz, MC Groovz Dance Craze puts players on the dance floor for songs from popular artists. Enjoy dancing to many of your favorite tunes by Jessica Simpson, Jewel, Kevin Lyttle, DJ Jazzy Jeff & the Fresh Prince, KC and the Sunshine Band... just to name a few. Groove out in single player modes or bring friends out for multiplayer modes including: Just Dance, Dance Together, Dance Face Off and Dance Work Out. You can practice to become a better dancer, show off your talent, compete against a friend, and even get dance-tastic exercise. Plus, you can still boogie down using the Nintendo GameCube Controller. The game is available with a bundled dance pad, or available separately.' FROM games WHERE igdb_id = 50581 ON CONFLICT (game_id, language_code) DO NOTHING;
