INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Network Taisen Mahjong MJ2', 'The sequel to Sega Yonin Uchi Mahjong MJ, and the second overall entry in Sega''s MJ series of Riichi Mahjong arcade games. This game had a higher focus on online play than its predecessor, introducing the League Battle mode. In addition to the buttons, a touch screen was also added for ease of operation, something the original game lacked.' FROM games WHERE igdb_id = 165299 ON CONFLICT (game_id, language_code) DO NOTHING;
