INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chromadrome', 'This game is the successor to Chromentum. Basically, the game is an arcade racer. You control one of the Chromates, a golden Chromate, while it "drives" along a road, where obstacles, loops, gaps, etc. are in it''s way. You have to make sure that the Chromate you control does not fall from the track. For this purpose, you will either dodge stationary Chromates or shoot at them to get them out of the way.' FROM games WHERE igdb_id = 73511 ON CONFLICT (game_id, language_code) DO NOTHING;
