INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gretzky NHL 2005', 'Experience the look, feel, and passion of hockey in Gretzky NHL 2005. This game features players with detailed facial animations; EyeToy functionality, which lets you put your face in the game; and enhanced arenas complete with arena-specific game intros, goal horns, and interactive crowds. Gretzky NHL 2005 offers a variety of gameplay modes, including Tournament, with customizable tournaments; Franchise, where you can act as the owner; Online, with downloadable rosters; and Rivalry, which lets you revisit heated matchups.' FROM games WHERE igdb_id = 24162 ON CONFLICT (game_id, language_code) DO NOTHING;
