INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('psyvariar-2-the-will-to-fabricate', 5993, '2004-02-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ps4ceh9kll9gu1xjbjwl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5hs6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psyvariar 2: The Will to Fabricate', 'Psyvariar 2: The Will to Fabricate (サイヴァリア2: THE WILL TO FABRICATE?) is a vertically scrolling shoot ''em up developed by SKONEC Entertainment and distributed by Success. It is the sequel to the 2000 title, Psyvariar. The game was initially developed for the Sega NAOMI arcade platform, and was released in Japanese arcades in November 2003. A Dreamcast version was released on February 26, 2004, and ports to both the PlayStation 2 and Xbox were released later that year.' FROM games WHERE igdb_id = 5993 ON CONFLICT (game_id, language_code) DO NOTHING;
