INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ddr-festival-dance-dance-revolution', 269397, '2004-11-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9656.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DDR Festival Dance Dance Revolution', 'The first "catch up" Japanese Dance Dance Revolution title. Most of the songlist consists of new Konami originals from Dance Dance Revolution ULTRAMIX and Dance Dance Revolution EXTREME CS (America), along with a few new licenses, some of the licenses from Dance Dance Revolution EXTREME CS (America), some old Konami original DDR songs, and two new KONAMI originals. Song list as a result has a large emphasis on Bemani crossovers than most Japanese CS DDR releases. Of the 55 Konami originals in DDR FESTIVAL, only 19 are original DDR songs/original remixes. Also, it is the only Japanese DDR without Dancemania licenses, hence no Dancemania advertisement is featured in the attract mode.' FROM games WHERE igdb_id = 269397 ON CONFLICT (game_id, language_code) DO NOTHING;
