INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Holiday World', 'Holiday World is a resort management simulation where players develop vacation destinations across beach islands, African safaris, and underwater locations. Players construct hotels, attractions, and infrastructure while catering to diverse tourist preferences - from families seeking playgrounds to adventure tourists wanting diving facilities. The game features competitive elements as players navigate limited building space and manage finances, with options for both legitimate business strategies and sabotage mechanics. Players directly control staff members to organize events, maintain facilities, and protect their resort from rival businesses.' FROM games WHERE igdb_id = 93126 ON CONFLICT (game_id, language_code) DO NOTHING;
