INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sprung', 'Sprung puts players in the shoes of either Becky or Brett in a conversation-based visual novel that mostly consists of dialogue. Sprung can be regarded as a dating sim, though the linearity and variety in the game (as well as its humor) also lend it to being an adventure game. The game was one of the first dating simulation games to have a wide commercial release in North America.' FROM games WHERE igdb_id = 20209 ON CONFLICT (game_id, language_code) DO NOTHING;
