INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empire of Atlantis', 'Rodrigo, the fisherman''s son one day finds a letter in a bottle on the beach. With some help of his grandfather he understands that it tells him how to find the famous lost city of Atlantis. Now Rodrigo and his grandfather along with their dog Uzo sets out on a journey to find the long lost island.' FROM games WHERE igdb_id = 66950 ON CONFLICT (game_id, language_code) DO NOTHING;
