INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Popmundo', 'Popmundo is an online role-playing game and community where the players strive for fame in a virtual music industry. You start the game as a complete nobody with nothing but your hopes and dreams. You can practice your music, play a few gigs, and begin to build a fanbase. Play your cards right and you''ll soon be touring the world, cutting chart-topping records, and leaving a wake of tantalizing scandals behind you!' FROM games WHERE igdb_id = 307602 ON CONFLICT (game_id, language_code) DO NOTHING;
