INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sip-se-safety-is-power', 302386, '2004-12-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co88uw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'S.I.P. SE: Safety is Power', 'The story revolves around a 23 year old unemployed NEET, Makoto Asaka, who is otherwise an "ordinary" citizen of Wakui City living in a rundown apartment. Makoto doesn''t have any money but has been skirting the law for some time through tax evasion, abuse of Japan''s basic "National Pension System", and odd jobs or "gigs" working under the table, becoming more behind on his fiscal obligations by the day. However, there is another odd phenomenon that has developed in Wakui City that Makoto did not immediately become aware of known as the "New Stalking Law", which grants protection and partial asylum to qualified candidates who have garnered the attention of unscrupulous parties. This system was put in place at Wakui City to divert resources to an emerging problem that the local police could not manage on their own, and is designed for rather extreme cases. In order for it to work, the "PG (Public Guardian) System" was created to assign benefactors who perform tasks on the behalf of their clients.' FROM games WHERE igdb_id = 302386 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 302386 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
