INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Constance the Barbarian', 'Constance the Barbarian - A humourous take on Conan the Barbarian/Xena Warrior Princess, with a dash of Monkey Island. Originally made for September 04 MAGS, and as a learning project. But decided to make it as a demo/teaser for a larger more involved game. I won''t hazard a release date at this point. I''m mostly improving my artwork skills.' FROM games WHERE igdb_id = 320050 ON CONFLICT (game_id, language_code) DO NOTHING;
