INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi Connection', 'The Tamagotchi Connection, or the Tamagotchi Plus is the first modern release of the Tamagotchi virtual pet, debuting in Japan on March 20, 2004 and in North America on August 15, 2004. The Tamagotchi Connection was the first Tamagotchi release to use Tamacom, an Infrared feature that connects two Tamagotchi pets, allowing them to play games, exchange presents, and give birth to offspring. It features characters from both version of the the classic Tamagotchi (1996) and the Mesutchi and Osutchi (1997), as well as several new characters.' FROM games WHERE igdb_id = 229942 ON CONFLICT (game_id, language_code) DO NOTHING;
