INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Michigan: Report from Hell', 'Michigan: Report from Hell, released as Michigan in Japan, is a survival horror game developed by Grasshopper Manufacture and published by Spike. It was released in Japan on August 5, 2004, in Europe on September 30, 2005, and in Australia in 2005. This game was never released in North America. Directed by Akira Ueda and planned by Goichi Suda, the game focuses on a news crew for the fictional ZaKa TV, dedicated to covering strange phenomena. The game is unique in the sense that it is played almost entirely though the viewfinder of a camera; and the game is lost if the player runs out of film before solving the mysteries in a mission.' FROM games WHERE igdb_id = 26294 ON CONFLICT (game_id, language_code) DO NOTHING;
