INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('midnight-race-club-supercharged--1', 69052, '2004-01-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/r7lv1davlhr3prp4wonn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scn95s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Race Club: Supercharged!', 'Midnight Race Club: Supercharged! is the second racing game from the developers behind the notorious Big Rigs: Over the Road Racing. Unlike Big Rigs, it has proper collision detection, unintentionally removing one of the quirks that made the previous game famous. Midnight Race Club was originally intended to be a single package along with Big Rigs, but GameMill decided to split the two early in development. For this reason, both games share an identical UI and near-identical gameplay.' FROM games WHERE igdb_id = 69052 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 69052 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
