INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Souhide Series: Omatsuri-zukushi', 'The summer festival that everyone enjoyed is now available as an easy mini-game collection! There are 4 mini-games: goldfish scooping, yo-yo fishing, sauce senbei split, and ring throwing, and if you clear it, an expert mode will appear in each game. You can get lottery tickets according to the score you played, and you can collect the items you took in the lottery. In addition, if you clear certain conditions, a hidden game will appear, and you can enjoy it as many times as you want.' FROM games WHERE igdb_id = 288631 ON CONFLICT (game_id, language_code) DO NOTHING;
