INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '112 Reddings Helikopter', '112 Reddings Helikopter is an action game that takes place in the cities of Amsterdam and Berlin. Completely remodeled to give the feeling of flying over the city in a helicopter. The player has a total of 20 missions to complete, these are dangerous missions with the ultimate goal to bring the person at risk to safety within a limited amount of time. The fires, traffic accidents, chemical disasters, armed robbery, factory accidents, sudden heart attacks and rescues from tall buildings are some of the many situations that will occur.' FROM games WHERE igdb_id = 290064 ON CONFLICT (game_id, language_code) DO NOTHING;
