INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('showdown-legends-of-wrestling', 6051, '2004-06-22', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4yv9.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Showdown: Legends of Wrestling', 'Showdown: Legends of Wrestling features more than 70 of the greatest wrestlers throughout history. Send your favorite wrestlers to the squared circle for bone-breaking matches, including Table, First Blood, Ladder, Cage, and Battle Royal. Create dream matches, unlock classic feuds, and customize your own wrestler. You''ll travel down the path of pain in the new era-based career mode. If you can master the new Ready-To-Brawl controls, you''ll be prepared to take on the icons of professional wrestling.' FROM games WHERE igdb_id = 6051 ON CONFLICT (game_id, language_code) DO NOTHING;
