INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Every Extend', 'A freeware game from Japanese software house OMEGA, Every Extend is a top-down action game (over a 3D background) in which you control a bomb - literally, a bomb - which you must maneuver for maximum damage. Enemy cubes of various kinds move around the playfield and by triggering an explosion at the right moment you can create massive chain reactions which wipe your enemies out.' FROM games WHERE igdb_id = 94573 ON CONFLICT (game_id, language_code) DO NOTHING;
