INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Void War', 'Void War is a single-player 3D, First-Person Space Dogfight action game for Windows PCs. The player may fly any of six starfighters in a space arenas called "Void Points" bounded by pylons that pull fighters back into the battle should they stray to far from the action. Void War''s action includes Newtonian-style physics and elements such as gravitational pulls (in a nod to the great-grandaddy of computer games, "Spacewar").' FROM games WHERE igdb_id = 73668 ON CONFLICT (game_id, language_code) DO NOTHING;
