INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War in the Pacific', 'War in the Pacific: The Struggle Against Japan 1941-1945 is a classic strategy game, based on the award winning Uncommon Valor game engine. The scale is 60 miles per hex and losses are individual vehicles, aircraft, guns and squads. Since half the planet Earth is covered by the titanic Pacific struggle, the game is massive in scope, covering thousands of ships tens of thousands of aircraft.' FROM games WHERE igdb_id = 27643 ON CONFLICT (game_id, language_code) DO NOTHING;
