INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Ages 2500 Vol. 13: OutRun', 'OutRun is a PS2 upgrade of the 1986 arcade release of OutRun, presented entirely in 3D. Whereas the "original" mode is almost identical to the arcade game (with an option to switch between the slightly different Japanese and overseas courses), an "arrange" mode offers an entirely new course, rival cars and more mountainous terrain to take advantage of the 3D visuals. There is also an arranged soundtrack.' FROM games WHERE igdb_id = 100024 ON CONFLICT (game_id, language_code) DO NOTHING;
