INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania-iidx-11-iidx-red', 94026, '2004-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hvi.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania IIDX 11 IIDX Red', 'IIDX Red is one of the many titles in Konami''s IIDX rhythm game series, featuring more than 80 tracks, primarily from the arcade version of the same title. As usual for the beatmania series, the player is given seven piano keys and a turntable, and must play along with the notes that scroll down the screen to play the music. All of the game modes from the previous title have returned: Arcade, Expert, Class, Beginner''s, Free, Training, and Gallery. The game also includes support for Internet score ranking (now discontinued) and custom-made Arcade courses.' FROM games WHERE igdb_id = 94026 ON CONFLICT (game_id, language_code) DO NOTHING;
