INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Ultimate Vol. 17: Taisen! Bakudan Poi Poi', 'Taisen Bakudan Poi Poi: Sometime in the year 20XX, a super computer goes awry and ordinary citizens are recruited into a virtual world where everyone hefts massive bombs. Once hefted, bombs may be hurled at opponents in a frenetic blast ''em up. Run around the digital landscape, gather a bomb and then time your attacks against roving combatants while being pursued by other bomb toting miscreants.' FROM games WHERE igdb_id = 203357 ON CONFLICT (game_id, language_code) DO NOTHING;
