INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Ages 2500 Vol. 10: After Burner II', 'Sega Ages 2500 Series Vol. 10: After Burner II is a Shoot-''Em-Up game, developed by Sims and published by Sega. After Burner II is an upgrade of the original 1988 arcade release of After Burner II, being presented entirely in 3D. Aside from this, it is essentially the same as before but with extra options such as unlimited continues. There is an "arranged" mode which lets you play as different planes, but it does not significantly affect gameplay.' FROM games WHERE igdb_id = 64900 ON CONFLICT (game_id, language_code) DO NOTHING;
