INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop''n Taisen Puzzle Dama Online', 'Pop''n Taisen Puzzle Dama Online is a block-building game. It is part of the Pop''n Music series and Taisen Puzzle-Dama series. The gameplay is similar to the others Taisen Puzzle-Dama games, just the balls have been changed to Pop-kuns instead, in order to fit the Pop''n music theme. The game also uses an online feature to download and unlock content, such as secret characters and songs.' FROM games WHERE igdb_id = 281402 ON CONFLICT (game_id, language_code) DO NOTHING;
