INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stalingrad', 'Stalingrad is a real-time strategy title that places gamers in the middle of the most dramatic periods of World War II, covering major events from June 1942 till January 1943. Built-up upon the enhanced Enigma Engine, the game offers faithful historical recreation of the Stalingrad area, vast tactical options and more than 150 units at your command.' FROM games WHERE igdb_id = 177096 ON CONFLICT (game_id, language_code) DO NOTHING;
