INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EyeToy: Monkey Mania', 'EyeToy: Monkey Mania (also known as Saru Eye Toy Oosawagi: Wakki Waki Game Tenkomori!! in Asia, Japan, and Korea) is a party game that requires the EyeToy camera to play. It is based on Ape Escape and the monkeys in the game are guided through 50 minigames. Up to four players can play together. The game is available with a silver camera or without for those who may already have the EyeToy.' FROM games WHERE igdb_id = 44677 ON CONFLICT (game_id, language_code) DO NOTHING;
