INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Notpron', 'Notpron is an online puzzle game and internet riddle created in 2004 by German game developer David Münnich. It has been hailed by fans, journalists, and Münnich himself as "the hardest riddle available on the internet". Regarded as one of the first of the online puzzle game genre, Notpron follows a standard puzzle game layout, where the player is presented with a webpage containing a riddle and must find the answer to the riddle in order to proceed to the next webpage.' FROM games WHERE igdb_id = 202394 ON CONFLICT (game_id, language_code) DO NOTHING;
