INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duel Masters: Kaijudo Showdown', 'Get ready for intense tournament battles in this card-battling game that features characters from the Duel Masters animated series. Kaijudo Showdown challenges you to build a fighting deck from 300 Duel Masters cards, which you''ll need defeat your enemies. As you duel various opponents, you''ll improve your skills and solve the mystery of the missing artifacts. With a Game Boy Advance link cable, you can battle against or trade cards with your friend.' FROM games WHERE igdb_id = 24257 ON CONFLICT (game_id, language_code) DO NOTHING;
