INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Hall of Fame: The Gottlieb Collection', 'Pinball Hall of Fame: The Gottlieb Collection is a pinball video game developed by FarSight Studios and published by Crave Entertainment. The tables in the game are recreations of real tables. The game was later released as Gottlieb Pinball Classics, published by System 3, in Europe and Australia. This expanded version featured additional tables and was released in North America on Wii and PSP under the original name, Pinball Hall of Fame: The Gottlieb Collection.' FROM games WHERE igdb_id = 4067 ON CONFLICT (game_id, language_code) DO NOTHING;
