INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gyakuten Saiban 3', 'The third installment of the Gyakuten Saiban/Ace Attorney series of text adventure video games. It is the last installment in the Gyakuten Saiban Trilogy. In addition to featuring three episodes in which Phoenix Wright faces off against a mysterious new prosecutor named Godot, the game also features the first two cases of Mia Fey''s law career. Like the other two games in the trilogy, it was first a Game Boy Advance exclusive title and only released in Japan (until the Nintendo DS port in 2007).' FROM games WHERE igdb_id = 221290 ON CONFLICT (game_id, language_code) DO NOTHING;
