INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lusternia: Age of Ascension', 'Lusternia is a text based multi-player game (sometimes called a MUD). When you create a character and log in, you join adventurers from all over the globe who will share in the trials and tribulations found only through intensive roleplaying. Some dismiss text games as retro, but many others find nothing can compare to the dynamic experience hearkening back to pen and paper RPGs.' FROM games WHERE igdb_id = 122848 ON CONFLICT (game_id, language_code) DO NOTHING;
