INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shaman King: Power of Spirit', 'Shaman King follows the story of Yoh Asakura, a junior high student who has the rare power to communicate with ghosts and spirits. In the game, you''ll assume the role of Yoh as he strives to become the next Shaman King. Guide Yoh across multiple stages filled with dangers, enemies, and traps in an effort to stop an evil shaman from resurrecting the Guardian of Demons. Master various fighting techniques as you encounter characters and locales from the Shaman King TV series and comics.' FROM games WHERE igdb_id = 43592 ON CONFLICT (game_id, language_code) DO NOTHING;
