INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beef Drop', 'Beef Drop is a port of the popular arcade game Burgertime, which Ken Siders first ported to the Atari 5200 and 8-bit computers. This version of Beef Drop beature POKEY sound support, for much better audio than the 7800 can produce without this chip. The 7800 version also features better graphics than the 5200/8-bit version, making the 7800 version the definitive release of Beef Drop.' FROM games WHERE igdb_id = 14706 ON CONFLICT (game_id, language_code) DO NOTHING;
