INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revector', 'Your goal is to out score your opponent in a 7 minute timed match. You can score points by shooting your opponent or by picking up power-up items. Revector allows you to take-on another player head-to-head, or a challenging CPU opponent. Revector features a rather unique vehicle control system with the joystick controling both rotation and thrust. Power-up''s include points, health, energy, weapons, invisibility and more ...' FROM games WHERE igdb_id = 46516 ON CONFLICT (game_id, language_code) DO NOTHING;
