INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('taikou-risshiden-v', 172698, '2004-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co686q.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taikou Risshiden V', 'Taikou Risshiden V is the latest title of a Japanese video game series Taikou Risshiden (turn-based sandbox role-playing video games/turn-based strategy) produced by Koei. It was released on PC and PlayStation 2 in 2004 followed by a port to PlayStation Portable in 2009. The first title of the series was released on NEC PC-9801 in 1992 followed by ports to Super Famicom and Genesis/Mega Drive. It was later re-released on the Wii Virtual Console on September 1, 2009, ported from the Super Famicom version. The name of the game roughly means "the Taikou''s success story". The characters are taken from the Momoyama period in Japan. In the previous Taikou Risshiden IV, a character was selected from the choices of a samurai, a ninja or a merchant. In Taikou Risshiden V, new roles include a blademaster, a pirate, a doctor, a tea master, and a blacksmith, counting eight roles in total. The player meets various historical figures of the era in the game.' FROM games WHERE igdb_id = 172698 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 172698 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
