INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cricket 2004', 'Cricket 2004 is based on the sport of Cricket, developed by HB Studios for the EA Sports catalog. It features full day-night matches, all new weather effects and pitch types. The game contains the licenses of all the international teams registered to the International Cricket Council for the year 2003, with the official Cricket 2003 World Cup fully playable along with many more tournaments. Domestic Teams for England and Australian leagues are fully licensed.' FROM games WHERE igdb_id = 94521 ON CONFLICT (game_id, language_code) DO NOTHING;
