INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tails Soccer', 'Tails Soccer is an LCD game created for distribution at McDonald''s restaurants. They were offered as a part of Happy Meals for a limited time in 2004. The game has similarities to Knuckles Soccer. The objective of the game is for Tails to block Soccer balls from entering the net behind him. Stopping 15 balls will advance the level by 1 and increase the game speed. If 5 soccer balls are missed then the game will end.' FROM games WHERE igdb_id = 162521 ON CONFLICT (game_id, language_code) DO NOTHING;
