INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casa dos Artistas', 'Casa dos Artistas is a simulation game based on the reality show by the same name, developed by Green Land Games and published by Cia. do Software in collaboration with SBT. Choose your character, define your personal traits such as character, stamina, enthusiasm, hygiene, libido, and charisma, and enter the competition! You must win over the participants and the public, trying to stay in the House until the grand finale. To do so, date, flirt, fight, talk, act, sing, dance, do everything to please everyone, use all your imagination to win the grand final prize.' FROM games WHERE igdb_id = 163701 ON CONFLICT (game_id, language_code) DO NOTHING;
