INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taxi Rider', 'Taxi Rider is a game about driving a taxi and getting customers to their destination in time, similar to the arcade concept of SEGA''s Crazy Taxi series. The player is employed by a local taxi firm set in the fictional Nijiiro, as well as the adjoining areas such as the residential Dream Hills, the Coast Amusement Center and Dragon Peak.' FROM games WHERE igdb_id = 43457 ON CONFLICT (game_id, language_code) DO NOTHING;
