INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Croket! 4: Bank no Mori no Mamorigami', 'Croket! 4: Bank no Mori no Mamorigami is a Game Boy Advance video game released exclusively in Japan. The game combines turn-based exploration with side-scrolling combat mechanics. Set in the Forest of Banks, players progress through the game by battling enemies, navigating story branches, and encountering various rivals. The game features a combo-based combat system, support characters, and multiple possible endings.' FROM games WHERE igdb_id = 49549 ON CONFLICT (game_id, language_code) DO NOTHING;
