INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatal Frame II: Crimson Butterfly - Director''s Cut', 'Crimson Butterfly is the second installment in the Fatal Frame series, although not a direct sequel to the first title, Fatal Frame. The story follows twin sisters Mio and Mayu as they explore an abandoned village and experience encounters with the paranormal. Players must use the Camera Obscura to defeat ghosts and uncover the secrets of the village. Fatal Frame 2: Crimson Butterfly - Director''s Cut includeds improved visuals, audio, and new gameplay modes.' FROM games WHERE igdb_id = 24161 ON CONFLICT (game_id, language_code) DO NOTHING;
