INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWE Day of Reckoning', 'Hit the ropes against WWE''s top superstars in WWE Day of Reckoning, which features an all-new story mode filled with deception and betrayal. As your own created wrestler, you can rise up the ranks from the "minor leagues" of sports entertainment all the way to prime-time WWE programming. You can choose your favorite WWE Divas and go head-to-head in a Bra & Panties match. Each wrestling star, including Legends, can target specific body parts to wear down opponents.' FROM games WHERE igdb_id = 4571 ON CONFLICT (game_id, language_code) DO NOTHING;
