INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ayumu Kasuga''s Mail Order Life', 'Ayumu Kasuga''s Mail Order Life is a fanmade interactive Osaka simulator from hirahira.net for PC. Osaka spends time in her room and occasionally walks out, possibly to a part-time job. Afterwards, she comes back with money used by the player to buy various items that appear on TV along with Chiyo-chichi.' FROM games WHERE igdb_id = 166443 ON CONFLICT (game_id, language_code) DO NOTHING;
