INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Futari ha Precure: Arienai! Yume no Sono ha Daimeikyuu', 'The first ever video game based on the anime of the same name, this is a puzzle platforming game in which the player guides Cure Black and Cure White through a series of puzzle stages. There are nine regular stages and one boss battle stage per world. The player needs to switch from one character to the other in order to bypass obstacles or reach parts of each stage.' FROM games WHERE igdb_id = 49569 ON CONFLICT (game_id, language_code) DO NOTHING;
