INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gooka: The Mystery of Janatris', 'Gooka - The Mystery of Janatris is a sequel to the game called just Gooka which was released in 1997 for the fans of adventure games. Both games are based on books by Richard D. Evans. Once again, the player is taken to the strange world on the planet of Janatris. Once again, Gooka is the main hero of the day. Once again, he finds himself in trouble.' FROM games WHERE igdb_id = 71426 ON CONFLICT (game_id, language_code) DO NOTHING;
