INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Berusky 2', 'Berusky 2 (Bugs Escape 3D) is a game that challenges your visual/spatial thinking and ability to find a way to resolve a logic task. Using five bugs, you''ll go through an adventure full of various puzzles spread across nine episodes. Individual episodes differ in appearance and difficulty, which increases throughout the game.' FROM games WHERE igdb_id = 142045 ON CONFLICT (game_id, language_code) DO NOTHING;
