INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('def-jam-fight-for-ny', 3875, '2004-09-20', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9xme.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nsxeemb8ahgf9sqvj3ex.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Def Jam: Fight for NY', 'The ultimate hip-hop fueled fighting game, Def Jam Fight For NY challenges players to step into the shoes of a ruthless street fighter battling for control of the hip-hop underground. The game features an all-new fighting engine including weapons, interactive environments and five unique fighting styles that can be combined to form dozens of customized hybrid styles for the ultimate edge on the streets. Def Jam Fight For NY features more than 40 of the most well-known artists and personalities in hip-hop today, including Busta Rhymes, Carmen Electra, Lil'' Kim, Ludacris, Method Man, Redman, Sean Paul, Slick Rick, Snoop Dogg, and many more. * New Fighting Engine -- A new fighting engine challenges you to master multiple fighting disciplines, take advantage of interactive environments, and utilize dozens of weapons to make a name for yourself. * Three Times the Length of the Original Def Jam VENDETTA -- It''s going to take more than 90 fights in 20-plus venues to win control of the streets. * 40 of the Biggest Hip Hop Artists and Celebrites -- Starring and music by the hottest names in hip hop from Def Jam and beyond -- look for appearances by Busta Rhymes, Carmen Electra, Fat Joe, Flava Flav, Freeway, Ghostface, Ice T, Joe Budden, Kimora Lee Simmons, Lil'' Kim, Ludacris, Method Man, Redman, Sean Paul, Slick Rick, Snoop Dogg, Xzibit, and many more. * Five Brutal Fighting Styles -- Master each fighting style: street fighting, kickboxing, martial arts, wrestling, and submission fighting. Combine up to three styles to create devastating hybrid-styles, complete with new "blazin'' moves" to finish off your opponent. * 22 Interactive Venues -- From destructible environmental objects to rowdy spectators who like to "get involved," the 22 venues are the ultimate weapon. * Create-A-Street Fighter -- Build your own street-ready fighter and outfit him with thousands of pieces of unlockable licensed gear, tattoos, and even bling from the Jeweler to the stars, Jacob the Jeweler. * Represent Your Crew Online -- Join a crew and own the mean streets of NYC. Move onto the international stage and take on all-comers with online play for the PlayStation 2.' FROM games WHERE igdb_id = 3875 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 3875 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
