INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Genesis Evangelion: Shinji Ikari Raising Project', 'Neon Genesis Evangelion: Shinji Ikari Raising Project (新世紀エヴァンゲリオン 碇シンジ育成計画 Shin Seiki Evangerion: Ikari Shinji Ikusei Keikaku) is a computer game based on the anime series Neon Genesis Evangelion. The player assumes control of Shinji Ikari, the protagonist and main character of the normal Neon Genesis Evangelion series, in the expanded alternate universe that was glimpsed upon for a few moments in the TV episode 26. Basically, the player decides Shinji''s fate in how he lives his life. The story begins with the attack of the 3rd Angel, much like the anime. Different decisions and actions lead to various outcomes etc.' FROM games WHERE igdb_id = 75878 ON CONFLICT (game_id, language_code) DO NOTHING;
