INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Alive: Extreme Encounter', 'Crimson Alive: Extreme Encounter is a Japanese 2D fighting game in a fantasy/sci-fi world. The story is all in Japanese, menus and short texts before fights are in English. It''s a typical "Doujin" game for hobbyists. The Game is based on a 2D Fighter Maker engine and manga alike graphics.' FROM games WHERE igdb_id = 125489 ON CONFLICT (game_id, language_code) DO NOTHING;
