INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Micro Life', 'Our AI based game teaching kids about the harsh realities of life. Dont eat? You die. Can’t defend yourself? You die. Get sick and don’t get quarantined? You die and so does everyone else. Despite all these high jinks – it won Best Game at the Flash Film Festival in New York.' FROM games WHERE igdb_id = 236627 ON CONFLICT (game_id, language_code) DO NOTHING;
