INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Target: Terror', 'Terror puts you in the place of an elite anti-terrorist agent who is charged with protecting the U.S. from all terrorist activities. With a full scale assault spanning the entire U.S., this is your chance to show terrorists who is in charge. Eliminate the seemingly endless waves of enemies with an assortment of high-tech weapons you have in your arsenal.' FROM games WHERE igdb_id = 5213 ON CONFLICT (game_id, language_code) DO NOTHING;
