INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duel Masters: Sempai Legends', 'Based on the Duel Masters Trading Card game in Japan, Duel Masters: Sempai Legends puts you in the role of a kohai (junior duelist). Your grandfather, a great Sempai (senior duelist), gives you a valuable Duel Masters card, which is soon stolen by a mysterious man. Now it is up to you to travel to nearby towns and villages in hopes of regaining the stolen property. Along the way, you''ll face many opponents in Duel Masters tournaments with the hope of one day becoming a professional Duelist.' FROM games WHERE igdb_id = 49198 ON CONFLICT (game_id, language_code) DO NOTHING;
