INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Quiet Weekend in Capri', 'A Quiet Weekend in Capri is a first-person, point and click adventure. The player is a tourist visiting the famous island of Capri (Italy) for the very first time. Suddenly, something strange happens. Almost all the people disappear and those who are left seem to know the protagonist. The player should explore the island, listen to what townsmen have to tell, wander through gardens, seashores, and old Roman ruins to discover the truth.' FROM games WHERE igdb_id = 71623 ON CONFLICT (game_id, language_code) DO NOTHING;
