INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters ''94 Re-bout', 'In celebration of its 10th anniversary, SNK re-releases the title that started its most famous fighting game franchise: The King of Fighters ''94. The remake smooths and upscales the original character sprites, includes completely new backgrounds with 3d elements, and adds the ability to edit the teams.' FROM games WHERE igdb_id = 80568 ON CONFLICT (game_id, language_code) DO NOTHING;
