INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ben Jordan: Paranormal Investigator', 'Ben Jordan: Paranormal Investigator is a freeware episodic point-and-click adventure video game for Microsoft Windows developed by Francisco Gonzalez of Grundislav Games. The game consists of eight individual episodes, or cases, with an overarching plot connecting them together.' FROM games WHERE igdb_id = 127124 ON CONFLICT (game_id, language_code) DO NOTHING;
