INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWF Panda Junior', 'Play as Alex or Emma as you discover the African continent in this educational WWF-endorsed game, the first in the Safari Adventure series - dedicated to an audience from 6 to 9 years old. Guided by the little WWF Panda and a forest ranger, you journey around and meet lots of different animals. Unfortunately, baddies such as the hunter Mr Mank and tourist Mr Rashburn will try to stop you from progressing.' FROM games WHERE igdb_id = 85800 ON CONFLICT (game_id, language_code) DO NOTHING;
