INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RalliSport Challenge 2', 'RalliSport Challenge 2 is a 2004 rally racing video game, and the sequel to the 2002 RalliSport Challenge. This game contains new features such as a cockpit cameras and ability to change car at the last moment. However, stats like total horsepower and number of gears have been eliminated from the car selection screen. Cars are split up into 5 categories with 2 subcategories each plus "Classic" cars. There are 4 paint schemes on each car and drivers must drive 31, 87, and 249 miles before unlocking a new one. By winning all championships in the career mode, all paint schemes for all cars are unlocked.' FROM games WHERE igdb_id = 5997 ON CONFLICT (game_id, language_code) DO NOTHING;
