INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nicktoons: Movin''', 'Nicktoons Movin'' is an EyeToy mini-game collection based on popular Nickelodeon cartoons. The game features 13 different mini-games with different skill levels based on series like SpongeBob SquarePants, Jimmy Neutron, The Fairly OddParents and Danny Phantom. The players steer a hang glider, control a bowling ball, defend a goal against pucks playing as a goalie, guide a submarine, zap ghosts, solve a classic puzzle by moving the pieces, and more - all by EyeToy registered movement of the player''s hands. The game features voice acting done by the original actors from the cartoons and the characters deliver numerous lines of dialog throughout the game.' FROM games WHERE igdb_id = 7982 ON CONFLICT (game_id, language_code) DO NOTHING;
