INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon: A Wonderful Life Special Edition', 'Harvest Moon: A Wonderful Life will span a lifetime on the farm and follow the drama that goes with it. Not only must you build and successfully run a farm, but you must also build a successful life with family and friends! This new Harvest Moon experience will take the best qualities of the series and add more...more animals, more vegetables and more drama! What sort of life will you live? A special edition version titled "A Wonderful Life Special Edition" was released on the PlayStation 2 in Japan in 2004 and North America in 2005. It was later re-released on the PlayStation 3 and PlayStation 4 with improvements upon lag issues rooting from the PlayStation 2 port.' FROM games WHERE igdb_id = 20482 ON CONFLICT (game_id, language_code) DO NOTHING;
