INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mermaid Melody: Pichi Pichi Pitch - Pichi Pichitto Live Start!', 'Mermaid Melody Pichi Pichi Pitch Pichitto Live Start! is a licensed game developed by Konami and published for the Game Boy Advance platform. It takes inspiration from the Dance Dance Revolution series, using music and characters from the anime of the same name. It includes all the songs from the first Mermaid Melody GBA game and adds more from the second half of the TV series.' FROM games WHERE igdb_id = 63793 ON CONFLICT (game_id, language_code) DO NOTHING;
