INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blasterball 2: Revolution', 'Blasterball 2: Revolution is the sequel to Blasterball Wild, an arcade brick breaker type game in the Blasterball series. The game plays like classic brick breaker games like Arkanoid except with the addition of power ups, obstacles/enemies, and several stages including bonus stages.' FROM games WHERE igdb_id = 73203 ON CONFLICT (game_id, language_code) DO NOTHING;
