INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Shattered Universe', 'The universe is not as you know it...Think Fast, Shoot Faster! All hands to battle stations! Get ready for a frenetic, adrenaline pumping experience in an entirely new breed of Star Trek.An intense,edgy high-energy space-combat action game set in the dark mirror universe of Star Trek: The Original Series classic-era setting, Star Trek Shattered Universe challenges the player to adapt to a new reality where everything once familiar is now a dark reflection - where the noble Federation is now an evil and relentless foe.' FROM games WHERE igdb_id = 4168 ON CONFLICT (game_id, language_code) DO NOTHING;
