INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'N', 'N is an award-winning 2D action/puzzle platformer reminiscent of Lode Runner: you''re a tiny stick figure running around in a puzzle-y world inhabited by enemies. But in N, there''s a twist: the ninja is driven not only by a thirst for gold, but also by a physics simulation. Expect to encounter death frequently, animated with hilarious ragdoll physics. N includes a built-in editor, called Ned. You can make your own levels to share with the community or hoard for yourself. Infinite levels, woo!' FROM games WHERE igdb_id = 8748 ON CONFLICT (game_id, language_code) DO NOTHING;
