INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jooleem', 'Jooleem is a simple yet extremely addictive puzzle game. There is only one rule: click on four marbles of the same color that form a rectangle. Time is constantly running out, but you can earn time (and points) by forming rectangles. The larger the rectangle, the more time and points are won. Jooleem is free and open source software.' FROM games WHERE igdb_id = 126121 ON CONFLICT (game_id, language_code) DO NOTHING;
