INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kenny vs. Spenny: Versusville', 'Based on the TV series Kenny vs Spenny (starring Kenny Hotz and Spencer Rice), Versusville is free to play and features 4 different games that can be played in real time in either single or multiplayer online modes. The four games are Residence Evil, Wasteball, Kart Dart & Grave Rave. High scores were featured on the website for the game when it was active.' FROM games WHERE igdb_id = 303021 ON CONFLICT (game_id, language_code) DO NOTHING;
