INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('same-game-and-robots', 41464, '2004-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ph3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Same Game and Robots', 'Strategy and planning is the name of the game regardless which title you choose to test your wits against. Learn to analyze and predict how the game will unfold to achieve the most points and successful completion. Welcome to the peaceful world of SameGame and the tense world of Robots. Either choice is an addicting path.  SAMEGAME - There are three different pieces on the board. Connect as many shapes of one type to score higher points and clear the board. The two variations of the game only have different game rules.  ROBOTS - Move the cursor to destroy all the Robots on the screen by making them collide into each other, by making them hit their left over scrap, or by using a bomb.' FROM games WHERE igdb_id = 41464 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41464 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
