INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dirty-pigskin-football', 39443, '2004-07-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yk6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirty Pigskin Football', 'This is Football with a twist. Rather than regularly suited up football players each with their own set of morals, we have got a completely unique cast of players who don''t know the meaning of the word. One of the featured teams is: The prisoners, in their traditional orange jail overalls. Then we have: The Hitman group, a group of assassinsall dressed in black suits and dark glasses, pleasant right? These men are all just urging to get their hands dirty. In total there are 12 teams in this game, various venues to play at, and the game also features a cool 4-player simultaneous play mode. With a play system that is easy to use, Pigskin welcomes all level of player to join in the action.' FROM games WHERE igdb_id = 39443 ON CONFLICT (game_id, language_code) DO NOTHING;
