INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubis 2', 'Cubis 2 is a puzzle video game that was released in 2004 by FreshGames. In Cubis 2, the player shoots different colored cubes into cubes that are already placed on the isometric game table. Once three of the same color are matched in a row or are stacked, the cubes disappear and the player earns points. Once the board is clear or enough points are earned, the player advances to the next board which features a new animated backdrop.' FROM games WHERE igdb_id = 93220 ON CONFLICT (game_id, language_code) DO NOTHING;
