INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Yakyuu Spirits 2004', 'Pro Yakyuu Spirits 2004 is a baseball game that allows players to compete in Japan''s professional baseball league, with licensed team and player names. The game features all 12 Nippon Professional Baseball teams, and both the Pacific League and Central League All-Star teams.' FROM games WHERE igdb_id = 92238 ON CONFLICT (game_id, language_code) DO NOTHING;
