INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riding Spirits II', 'Riding Spirits II adds more bikes, tracks and gameplay modes to deliver the PlayStation 2''s most comprehensive road bike racer. Gamers can now take to the road with faithfully reproduced motorcycles from famous European manufacturers such as Ducati, Aprilla, Triumph and BMW in addition to top models from Honda, Kawasaki, Yamaha and Suzuki plus Japan''s most famous tune shops Yoshimura and Moriwaki. And with engine sizes from 250cc to over 1000cc available Riding Spirits II boasts an impressive 330 bikes, that can be raced in 40 categories around 15 courses from across the globe, including Suzuka and Twin Link Motegi.' FROM games WHERE igdb_id = 43371 ON CONFLICT (game_id, language_code) DO NOTHING;
