INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rascal Racers', 'Eight wild animal characters are waiting for you to jump in the driver''s seat. Choose to guide Argyle the Aardvark, Paulie the Beaver or one of their friends across nine treacherous courses split over three locations. Your goal? That''s easy, to win all nine races in the RASCAL RACERS tournament of course ! Use missiles, force fields and grenades to put a stop to your opposition. Only the craziest drivers will have what it takes!' FROM games WHERE igdb_id = 43806 ON CONFLICT (game_id, language_code) DO NOTHING;
