INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breed', 'In Breed, you must take control of a squad of soldiers and win 18 different missions. They take place on tropical islands, Antarctica and even outer space. There is a variety of vehicles including tanks, buggies and fighter jets, ensuring that a range of control skills must be mastered. Everything you see can be blown up, with weapons including plasma guns, assault rifles and grenades.' FROM games WHERE igdb_id = 78822 ON CONFLICT (game_id, language_code) DO NOTHING;
