INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Jack: The Shadow of Aku', 'As the fearless and noble warrior, Samurai Jack, you are thrust into the future where the world has been conquered by your arch foe Aku. Master Jack''s signature moves to battle your way through 4 enemy-filled realms and 24 interactive levels. Meet your favorite friends and foes like the Scotsman, Mad Jack and more. Discover a portal that connects you with your ancestors who help guide you through burning villages and down hidden pathways. Free prisoners, dodge fireballs and sword strokes—ultimately defeat Aku once and for all!' FROM games WHERE igdb_id = 2823 ON CONFLICT (game_id, language_code) DO NOTHING;
