INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Realm of the Dead', 'Realm of the Dead is a gory, zombie-themed brawler set in medieval times. A terrible plague is sweeping the land turning everyone into zombies, and you take control of one of three different characters and battle your way through the game to rescue a noble count and uncover a conspiracy that threatens to bring chaos and turmoil to the whole realm.' FROM games WHERE igdb_id = 43210 ON CONFLICT (game_id, language_code) DO NOTHING;
