INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Boys: Miami Takedown', 'Mike Lowrey and Marcus Burnett of the Tactical Narcotics Team are back to fight crime in Bad Boys II. Based on the movie, Bad Boys II follows this unlikely duo as they try to stop illegal drug trade in Miami. Through 15 action-packed stages, you''ll play as either Mike or Marcus in first- or third-person viewpoints. Search for clues, wield a variety of weapons, and tear through fully destructible environments to complete a variety of mission objectives.' FROM games WHERE igdb_id = 5736 ON CONFLICT (game_id, language_code) DO NOTHING;
