INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('energy-airforce', 43380, '2004-10-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2nko.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kxj41eqlhnjgwzmyxxlq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Energy Airforce', 'Energy Airforce: is a PlayStation 2 game that focuses strictly on being an authentic flight simulator. All aircraft and weapons used in the game are either existing or prototypes used by the U.S. military. Realistic loads of weapons and fuel (although chaff and flares are unlimited) can be viewed from outside or from a realistic cockpit view. When flying the aircraft in cockpit view, the pilot''s leg can be seen depressing appropriately.' FROM games WHERE igdb_id = 43380 ON CONFLICT (game_id, language_code) DO NOTHING;
