INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fc-barcelona-club-football-2005', 267909, '2004-10-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co74ax.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FC Barcelona Club Football 2005', 'The follow-up edition to Codemasters'' multi-title soccer franchise (each dedicated to a single team in the UK and continental European football league and featuring unique presentation and other team-specific aspects), the 2005 series is powered by an accelerated game engine and new animation system to deliver faster and more responsive gameplay for precise control on the pitch. With twice the amount of official team content in each game, great skill moves and new game modes including Career, Practice and classic Scenarios (plus new clubs added to the line-up), the new Club Football 2005 range will bring players even closer to the heart of the action and the heart of their team.' FROM games WHERE igdb_id = 267909 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 267909 AND c.slug = 'codemasters' ON CONFLICT DO NOTHING;
