INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dora-the-explorer-super-spies', 49200, '2004-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/scdhttubhtwuiaxajckz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dora the Explorer: Super Spies', 'Seor Tucn, a master super spy, has a special mission for super spies Dora and Boots: Race to Tico''s workshop to warn him of Swiper''s plan to swipe his new rocket car. In this dangerous adventure, Dora and Boots need help from their friends, Backpack and Map, and you. To help them, you must find spy briefcases that contain special spy gadgets, such as spy glasses, rocket sneakers, a rope launcher, and more. You''ll need these items to explore levels ranging from a rainforest and a garden to a desert and a cavern.' FROM games WHERE igdb_id = 49200 ON CONFLICT (game_id, language_code) DO NOTHING;
