INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killzone: Collector''s Edition', 'The game is set in an era of space colonization where the Helghast Empire has recovered from its defeat in the First Helghan War and launched a blitzkrieg against the outer Interplanetary Strategic Alliance (I.S.A.) colony planet Vekta. Vekta''s orbital Strategic Defense (S.D.) platforms failed during the initial assault, allowing the Helghast to land swarms of soldiers onto the surface and making it all the more difficult for the outnumbered I.S.A. forces. This is the very rare steelbook of Killzone Collector''s Editon. It''s one of few games that exist for the PS2 that come with a steelbook, bonus DVD, and was limited to 250 copies per region.' FROM games WHERE igdb_id = 43422 ON CONFLICT (game_id, language_code) DO NOTHING;
