INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revolutionary Quest', 'The revolutionary quest is another quest from the Buka company, developed by VZlab. This adventure game with a third-person view will take us to the origins of the revolution, tell us about it, as well as about the people who participated (or allegedly participated) in this event.' FROM games WHERE igdb_id = 292594 ON CONFLICT (game_id, language_code) DO NOTHING;
