INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garfield', 'Garfield lets you play the role of the fat cat himself. As Garfield, you must clean up Odie''s mess before John comes home if you want to win a big piece of lasagna. It''s a race against the clock as you explore fully interactive environments and interact with familiar characters from the Garfield show. The game also includes minigames that let you race, cook lasagna, and play classic console games.' FROM games WHERE igdb_id = 5891 ON CONFLICT (game_id, language_code) DO NOTHING;
