INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('destruction-derby-arenas', 1171, '2004-01-09', 71, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jdnym2bec1n9n99305zr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destruction Derby: Arenas', 'The PS1 Destruction Derby titles would put you in the seat of a high powered vehicle, in either an arena or a track, and the target was to race to the finish, while causing as much destruction to the other cars as possible. Now comes the PS2 sequel. Because this is now on the PS2, the capabilities are much higher, so now there is a vastly improved graphics engine, physics engine, and levels. There are now loads of online play modes to try, with up to 19 other racers online with you, and now, the crashes are bigger than ever.' FROM games WHERE igdb_id = 1171 ON CONFLICT (game_id, language_code) DO NOTHING;
