INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kuma\War', 'Kuma\War is a free tactical first and third-person shooter game created by developer Kuma Reality Games. Kuma\War is an episodic game that re-creates real-world conflicts in video game format using information culled from news accounts, military experts, Department of Defense records and original research. Episodes consist of a playable mission, extensive background text, and often include interviews with military experts, soldiers and other actual participants in the events described.' FROM games WHERE igdb_id = 23563 ON CONFLICT (game_id, language_code) DO NOTHING;
