INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dennou Taisen: DroneZ', 'a single-player futuristic shooter. The player is guiding a female avatar through a virtual reality, representing the future world for humans living in suspended animation vats while their bodies are being cared for by insects and their minds are prevented from leaving the virtual world by its dominant AI. The task is for the character to jump/travel on discs representing memory bits in an organic computer, while avoiding wall mounted cannons, electrical fields and various aliens trying to stop you from escaping the virtual reality into the real world. The graphics are reminiscent of the movie TRON with a bright, neon style.' FROM games WHERE igdb_id = 202162 ON CONFLICT (game_id, language_code) DO NOTHING;
