INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prezzemolo in un Viaggio da Sogno', '"Prezzemolo in un Viaggio da Sogno" is the second PC video game based on the mascot of Gardaland , the dragon Parsley . It is the sequel to "Prezzemolo in una giornata da incubo" and, like its predecessor, in addition to being a point and click adventure , it has some voice actors from the animated series also inspired by Parsley.' FROM games WHERE igdb_id = 305292 ON CONFLICT (game_id, language_code) DO NOTHING;
