INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densetsu no Starfy 3', 'A short time after Densetsu no Starfy 2, everything was calm and everyone including Stafy was happy again, until another severe thunderstorm came and shook Pufftop Palace. This time, it is more severe than the ones in the past. A lightning struikes the Magic Jar, destroys it and Ogura is free again.' FROM games WHERE igdb_id = 6372 ON CONFLICT (game_id, language_code) DO NOTHING;
