INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternal Quest', 'Eternal Quest is a lavish and engaging title that combines all the vital elements of the third person adventure genre into one perfectly formed product. There is stunning action, glorious combat, a host of magic spells to use and abuse and hordes of enemies to meet and massacre. There is, of course, a brave and battle weary hero to guide to the ultimate prize of peace - and that''s you!' FROM games WHERE igdb_id = 43353 ON CONFLICT (game_id, language_code) DO NOTHING;
