INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Ultimate Vol. 22: Stylish Mahjong', 'Stylish Mahjong Usagi is a mahjong game that features different modes, the most special is the story mode one in which the player at the beginning of the game takes the role of a young high school student called Takeda (the player can unlock other characters playing the game) and will advance through the game winning mahjong matches.' FROM games WHERE igdb_id = 203359 ON CONFLICT (game_id, language_code) DO NOTHING;
