INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Bang Board Games', 'Finally, a suite of board games made just for the Mac! Checkers, Reversi, Mancalla, Backgammon, 4-In-A-Row, Tic-Tac-Toe and the Apple Design Award Winning Big Bang Chess are all included in this collection. Play solo against the computer, with a friend via iChat or email, or make new friends on the GameSmith game matching service. These OS X-only games integrate seamlessly with your iTunes, Address Book, iChat Buddy Lists and other Apple technologies. Fun and beautiful board games, made for the Mac, and made for you!' FROM games WHERE igdb_id = 78654 ON CONFLICT (game_id, language_code) DO NOTHING;
