INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid Prime Hunters: First Hunt', 'An episode in the Metroid Prime series which started on the GameCube, this game takes place between Metroid Prime and Metroid Prime 2: Echoes. Interstellar bounty hunter Samus Aran is sent to the distant Alimbic Cluster by the Galactic Federation to investigate a message saying that the source of ultimate power lies in this desolate part of the galaxy, once home to an advanced culture.' FROM games WHERE igdb_id = 119521 ON CONFLICT (game_id, language_code) DO NOTHING;
