INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyblade: G-Revolution', 'The G-Revolution is sweeping over the entire Beyblade world, and your job is to challenge the greatest Beybladers and collect valuable parts. Like previous entries in the Beyblade series, G-Revolution lets you pit your spinning top against others in different arenas. In your quest to become world champion, you can build a varied collection of blades, which you can customize with the Beyblade editor. Compete against more than 16 characters in a storyline taken straight from the Beyblade G-Revolution animated series.' FROM games WHERE igdb_id = 9726 ON CONFLICT (game_id, language_code) DO NOTHING;
