INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gefangen in der Drachenfestung', 'Join the PLAYMOBIL-kids Laura and Alex on an exciting trip into the world of knights. Princess Laura gets kidnapped from the evil wizard Grimmbart and captured in Dragon''s Castle. Squire Alex wants to rescue her. He needs to win the knights'' tournament as well as beating the dragon, other knights and the evil wizard. He needs to beat level 3 in 11 exciting minigames.' FROM games WHERE igdb_id = 255553 ON CONFLICT (game_id, language_code) DO NOTHING;
