INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Léidiàn Huáng: Pikachu Chuánshuō', 'Léidiàn Huáng: Bíkǎqiū Chuánshuō (also known as Pokémon Yellow) is a pirated game for the NES made by Shenzhen Nanjing. It''s generally regarded as being of higher quality compared to Shenzhen Nanjing''s other games. This game is basically a port of Pokémon FireRed / Pokémon LeafGreen Version and Pokémon Yellow Version mixed together with some changes to it.' FROM games WHERE igdb_id = 163097 ON CONFLICT (game_id, language_code) DO NOTHING;
