INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EyeToy: Groove', 'In this game, you are given many popular songs to choose from and dance to. Since this is the Eye Toy we are talking about, it is much more interactive. As lights shoot at buttons around the screen, you touch the buttons. Songs include: Music by Madonna Cheeky Holiday by The Cheeky Girls Move Your Feet by Junior Senior and much, much more.' FROM games WHERE igdb_id = 22250 ON CONFLICT (game_id, language_code) DO NOTHING;
