INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stargate SG-1', 'A side-scrolling mobile game based on the TV series Stargate SG-1, featuring four story-based missions: "Derelict", "Malfunction", "Paradise Lost", and "Aten''s Curse". Based on the hit TV series, this game presents various challenges across four thrilling missions. As Colonel Jack O''Neill, you''re the leader of the Stargate SG-1 team. From the surprise appearance of a Goa''uld mothership to the mysterious discovery of an ancient tomb, you and your team face snake-headed soldiers and other perils of the universe.' FROM games WHERE igdb_id = 280286 ON CONFLICT (game_id, language_code) DO NOTHING;
