INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mazera', 'Mazera is an adventure game created by Cold River Studios and published by Astraware for Palm OS and Pocket PC. The player plays Ix, who as a boy was captured by an alien race called the Mazerians and imprisoned in their zoo, until one day something happens that gives him a chance to escape. As Ix makes his escape, he must solve a large variety of puzzles and challenges so that he can return to his home planet Ixus.' FROM games WHERE igdb_id = 94679 ON CONFLICT (game_id, language_code) DO NOTHING;
