INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xuan-Yuan Sword: The Millennial Destiny', 'The game opens with an alternate version of the Battle of Fei River, a battle between Former Qin and Eastern Jin. It concludes with Eastern Jin''s surrender to Former Qin. Former Qin merged with Eastern Jin and united the entirety of China. On December 3, 2015, an animated series inspired by the game called Xuan Yuan Sword Luminary (軒轅劍：蒼之曜 / Ken En Ken: Aoki Kagayaki, literally "Xuan-Yuan Sword: Lights of the Bleak") was announced as a collaborative project with TV Tokyo and Studio Deen and began airing on October 2, 2018 in Mainland China, Taiwan, as well as Japan.' FROM games WHERE igdb_id = 86029 ON CONFLICT (game_id, language_code) DO NOTHING;
