INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ahriman''s Prophecy', 'Amaranth Games introduces Ahriman’s Prophecy, a beautiful fantasy world doomed to be destroyed by the demon, Ahriman. In a desperate attempt to stop the prophecy, the Daughters of Light send you, a young but powerful magic wielder, on a difficult quest to unlock the secrets of the prophecy and hopefully, learn how to stop it. If you enjoy classic RPGs like Final Fantasy 6 and Chrono Trigger, you’re going to love Ahriman’s Prophecy.' FROM games WHERE igdb_id = 10009 ON CONFLICT (game_id, language_code) DO NOTHING;
