INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-warriors-xtreme-legends', 12298, '2004-09-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45ju.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57a5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors: Xtreme Legends', 'Samurai Warriors: Xtreme Legends is an expansion disc for Samurai Warriors. Just like the Dynasty Warriors series, the aim of these expansions is solely to add more content to the game. Players can use the "Import" feature (through switching discs with the original game) to use all features of the original game. Without the original game disc, the player will only have access to the Xtreme Legends content. This offers four new characters (Imagawa Yoshimoto, Hashiba Hideyoshi, Honda Tadakatsu and Inahime) and a brand new mission and map. This also offers new weapons, items, skills, three new versus modes, a new survival mode, and fixes several problems. A new difficulty level, Novice is also added which is easier than Easy and targeted for beginners. Exclusive to Samurai Warriors Xtreme Legends, through the completion of special tasks, the player can earn Bonus Points in order to purchase special features. These features include additional costumes for characters, voice sound tests, lowering the difficulty required to unlock the fifth and sixth weapons and the ability to break the default limits for character''s stats. Methods of earning bonus points include the following: earning all of a character''s endings, unlocking rare items and weapons and successfully creating new characters.' FROM games WHERE igdb_id = 12298 ON CONFLICT (game_id, language_code) DO NOTHING;
