INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tom-clancy-s-ghost-recon-2', 1298, '2004-11-16', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yhn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hgfwswseltcmeuvqby4f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Ghost Recon 2', 'Set in the near future, Tom Clancy''s Ghost Recon 2 puts the player in the shoes of a highly trained operative who works as a part of the infamous military unit from the U.S. Special Forces only known as "Ghosts". The game is set in North Korea, where an evil general is diverting all the humanitarian aid to boost his forces and gain more political power in the process and it''s up to Ghosts to eliminate this threat. There is a single player campaign mode, where the player as part of the Ghosts, must take on the evil general in 11 different and quite long missions. There is also a multiplayer modes in both on and offline. The main campaign can be played through with a friend, or you can fight other players in multiple game modes spanning from a simple deathmatch to team based modes. New to this part of the series is the possibility to use a third person viewpoint, but the classic "From the eyes"-view is also available.' FROM games WHERE igdb_id = 1298 ON CONFLICT (game_id, language_code) DO NOTHING;
